comms.text:
@1 וּמַלִיל יְיָ עִם משֶׁה וַאֲמַר לֵהּ אֲנָא יְיָ:
@2 וְאִתְגְלֵיתִי לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקֹב בְּאֵל שַׁדָי וּשְׁמִי יְיָ לָא הוֹדָעִית לְהוֹן:
@3 וְאַף אֲקֵימִית יָת קְיָמִי עִמְהוֹן לְמִתַּן לְהוֹן יָת אַרְעָא דִכְנָעַן יָת אַרְעָא תּוֹתָבוּתְהוֹן דְאִתּוֹתָבוּ בָהּ:
@4 וְאַף קֳדָמַי שְׁמִיעַ יָת קְבֵילַת בְּנֵי יִשְׂרָאֵל דִי מִצְרָאֵי מַפְלְחִין בְּהוֹן וְדָכִירְנָא יָת קְיָמִי:
@5 בְּכֵן אֱמַר לִבְנֵי יִשְׂרָאֵל אֲנָא יְיָ וְאַפֵּיק יָתְכוֹן מִגוֹ דְחוֹק פָּלְחַן מִצְרָאֵי וֶאֱשֵׁיזֵב יָתְכוֹן מִפָּלְחָנְהוֹן וְאֶפְרוֹק יָתְכוֹן בִּדְרָעָה מְרָמָא וּבְדִינִין רַבְרְבִין:
@6 וֶאֱקָרֵיב יָתְכוֹן קדָמַי לְעַמָא וְאֶהֱוֵי לְכוֹן לֶאֱלָהּ וְתִדְעוּן אֲרֵי אֲנָא יְיָ אֱלָהָכוֹן דְאַפֵּיק יָתְכוֹן מִגוֹ דְחוֹק פָּלְחַן מִצְרָיִם:
@7 וְאָעֵיל יָתְכוֹן לְאַרְעָא דִי קַיֵמִית בְּמֵימְרִי לְמִתַּן יָתַהּ לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקֹב וְאֶתֵּן יָתַהּ לְכוֹן יְרֻתָּא אֲנָא יְיָ:
@8 וּמַלֵיל משֶׁה כֵּן לִבְנֵי יִשְׂרָאֵל וְלָא קַבִּילוּ מִן משֶׁה מִמַעְיַק רוּחָא וּמִפָּלְחָנָא דַהֲוָה קָשְׁיָא עֲלֵיהוֹן:
@9 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@10 עוּל מַלֵיל לְוָת פַּרְעֹה מַלְכָּא דְמִצְרָיִם וִישַׁלַח יָת בְּנֵי יִשְׂרָאֵל מֵאַרְעֵהּ:
@11 וּמַלִיל משֶׁה קֳדָם יְיָ לְמֵימָר הָא בְנֵי יִשְׂרָאֵל לָא קַבִּילוּ מִנִי וְאֵכְדֵין יְקַבֵּל מִנִי פַרְעֹה וַאֲנָא יַקִיר מַמְלָל:
@12 וּמַלִיל יְיָ עִם משֶׁה וְעִם אַהֲרֹן וּפַקֵדִנוּן לְוָת בְּנֵי יִשְׂרָאֵל וּלְוָת פַּרְעֹה מַלְכָּא דְמִצְרָיִם לְאַפָּקָא יָת בְּנֵי יִשְׂרָאֵל מֵאַרְעָא דְמִצְרָיִם:
@13 אִלֵין רֵישֵׁי בֵית אֲבָהָתְהוֹן בְּנֵי רְאוּבֵן בּוּכְרָא דְיִשְׂרָאֵל חֲנוֹךְ וּפַלוּא חֶצְרוֹן וְכַרְמִי אִלֵין זַרְעֲיַת רְאוּבֵן:
@14 וּבְנֵי שִׁמְעוֹן יְמוּאֵל וְיָמִין וְאֹהַד וְיָכִין וְצֹחַר וְשָׁאוּל בַּר כְּנַעֲנֵיתָא אִלֵין זַרְעֲיַת שִׁמְעוֹן:
@15 וְאִלֵין שְׁמָהַת בְּנֵי לֵוִי לְתוּלְדָתְהוֹן גֵרְשׁוֹן וּקְהָת וּמְרָרִי וּשְׁנֵי חַיֵי לֵוִי מְאָה וּתְלָתִין וּשְׁבַע שְׁנִין:
@16 בְּנֵי גֵרְשׁוֹן לִבְנִי וְשִׁמְעִי לְזַרְעֲיָתְהוֹן:
@17 וּבְנֵי קְהָת עַמְרָם וְיִצְהָר וְחֶבְרוֹן וְעֻזִיאֵל וּשְׁנֵי חַיֵי קְהָת מְאָה וּתְלָתִין וּתְלַת שְׁנִין:
@18 וּבְנֵי מְרָרִי מַחְלִי וּמוּשִׁי אִלֵין זַרְעֲיַת לֵוִי לְתוּלְדָתְהוֹן:
@19 וּנְסִיב עַמְרָם יָת יוֹכֶבֶד אֲחַת אֲבוּהִי לֵהּ לְאִנְתּוּ וִילִידַת לֵהּ יָת אַהֲרֹן וְיָת משֶׁה וּשְׁנֵי חַיֵי עַמְרָם מְאָה וּתְלָתִין וּשְׁבַע שְׁנִין:
@20 וּבְנֵי יִצְהָר קֹרַח וָנֶפֶג וְזִכְרִי:
@21 וּבְנֵי עֻזִיאֵל מִישָׁאֵל וְאֶלְצָפָן וְסִתְרִי:
@22 וּנְסִיב אַהֲרֹן יָת אֱלִישֶׁבַע בַּת עַמִינָדָב אַחָתֵהּ דְנַחְשׁוֹן לֵהּ לְאִנְתּוּ וִילִידַת לֵהּ יָת נָדָב וְיָת אֲבִיהוּא יָת אֶלְעָזָר וְיָת אִיתָמָר:
@23 וּבְנֵי קֹרַח אַסִיר וְאֶלְקָנָה וַאֲבִיאָסָף אִלֵין זַרְעֲיַת קֹרַח:
@24 וְאֶלְעָזָר בַּר אַהֲרֹן נְסִיב לֵהּ מִבְּנַת פּוּטִיאֵל לֵהּ לְאִנְתּוּ וִילִידַת לֵהּ יָת פִּינְחָס אִלֵין רֵישֵׁי אֲבָהַת לֵיוָאֵי לְזַרְעֲיָתְהוֹן:
@25 הוּא אַהֲרֹן וּמשֶׁה דִי אֲמַר יְיָ לְהוֹן אַפִּיקוּ יָת בְּנֵי יִשְׂרָאֵל מֵאַרְעָא דְמִצְרַיִם עַל חֵילֵיהוֹן:
@26 אִנוּן דְמַלְלִין עִם פַּרְעֹה מַלְכָּא דְמִצְרַיִם לְאַפָּקָא יָת בְּנֵי יִשְׂרָאֵל מִמִצְרָיִם הוּא משֶׁה וְאַהֲרֹן:
@27 וַהֲוָה בְּיוֹמָא דְמַלִיל יְיָ עִם משֶׁה בְּאַרְעָא דְמִצְרָיִם:
@28 וּמַלִיל יְיָ עִם משֶׁה לְמֵימַר אֲנָא יְיָ מַלֵל עִם פַּרְעֹה מַלְכָּא דְמִצְרַיִם יָת כָּל דִי אֲנָא מְמַלֵל עִמָךְ:
@29 וַאֲמַר משֶׁה קֳדָם יְיָ הָא אֲנָא יַקִיר מַמְלָל וְאֶכְדֵין יְקַבֵּל מִנִי פַּרְעֹה:
@30 וַאֲמַר יְיָ לְמשֶׁה חֲזֵי מַנֵיתָךְ רַב לְפַרְעֹה וְאַהֲרֹן אָחוּךְ יְהֵי מְתֻרְגְמָנָךְ:
@31 אַתְּ תְּמַלֵל יָת כָּל דִי אֲפַקְדִנָךְ וְאַהֲרֹן אָחוּךְ יְמַלֵל עִם פַּרְעֹה וִישַׁלַח יָת בְּנֵי יִשְׂרָאֵל מֵאַרְעֵהּ:
@32 וַאֲנָא אַקְשֵׁי יָת לִבָּא דְפַרְעֹה וְאַסְגֵיתִי יָת אַתְוָתַי וְיָת מוֹפְתַי בְּאַרְעָא דְמִצְרָיִם:
@33 וְלָא יְקַבֵּל מִנְכוֹן פַּרְעֹה וְאֶתֵּן יָת מָחַת גְבֻרְתִּי בְּמִצְרָיִם וְאַפֵּיק יָת חֵילִי יָת עַמִי בְנֵי יִשְׂרָאֵל מֵאַרְעָא דְמִצְרַיִם בְּדִינִין רַבְרְבִין:
@34 וְיִדְעוּן מִצְרַיִם אֲרֵי אֲנָא יְיָ כַּד אָרֵים יָת מָחַת גְבֻרְתִּי עַל מִצְרָיִם וְאַפֵּיק יָת בְּנֵי יִשְׂרָאֵל מִבֵּינֵיהוֹן:
@35 וַעֲבַד משֶׁה וְאַהֲרֹן כְּמָא דְפַקִיד יְיָ יָתְהוֹן כֵּן עֲבָדוּ:
@36 וּמשֶׁה בַּר תְּמָנָן שְׁנִין וְאַהֲרֹן בַּר תְּמָנָן וּתְלָת שְׁנִין בְּמַלָלוּתְהוֹן עִם פַּרְעֹה:
@37 וַאֲמַר יְיָ לְמשֶׁה וּלְאַהֲרֹן לְמֵימָר:
@38 אֲרֵי יְמַלֵל לְוָתְכוֹן פַּרְעֹה לְמֵימַר הָבוּ לְכוֹן אָתָא וְתֵימַר לְאַהֲרֹן סַב יָת חוּטְרָךְ וּרְמֵי קֳדָם פַּרְעֹה יְהִי לְתַנִינָא:
@39 וְעַל משֶׁה וְאַהֲרֹן לְוָת פַּרְעֹה וַעֲבָדוּ כֵן כְּמָא דְפַקֵיד יְיָ וּרְמָא אַהֲרֹן יָת חוּטְרֵהּ קֳדָם פַּרְעֹה וְקָדָם עַבְדוֹהִי וַהֲוָה לְתַנִינָא:
@40 וּקְרָא אַף פַּרְעֹה לְחַכִּימַיָא וּלְחָרָשַׁיָא וַעֲבָדוּ אַף אִנּוּן חָרָשֵׁי מִצְרַיִם בְּלַחֲשֵׁיהוֹן כֵּן:
@41 וּרְמוֹ גְבַר חוּטְרֵהּ וַהֲווֹ לְתַנִינַיָא וּבְלַע חֻטְרָא דְאַהֲרֹן יָת חֻטְרֵיהוֹן:
@42 וְאִתַּקַף לִבָּא דְפַרְעֹה וְלָא קַבִּיל מִנְהוֹן כְּמָא דְמַלִיל יְיָ:
@43 וַאֲמַר יְיָ לְמשׁה אִתְיַקַר (לפרש''י יַקִיר) לִבָּא דְפַרְעֹה סָרִיב לְשַׁלָחָא עַמָא:
@44 אִזֵיל לְוָת פַּרְעֹה בְּצַפְרָא הָא נָפֵיק לְמַיָא וְתִתְעַתַּד לְקַדָמוּתֵהּ עַל כֵּיף נַהֲרָא וְחֻטְרָא דְאִתְהֲפִיךְ לְחִוְיָא תִּסַב בִּידָךְ:
@45 וְתֵימַר לֵהּ יְיָ אֱלָהָא דִיהוּדָאֵי שַׁלְחַנִי לְוָתָךְ לְמֵימַר שַׁלַח יָת עַמִי וְיִפְלְחוּן קֳדָמַי בְּמַדְבְּרָא וְהָא לָא קַבִּלְתָּא עַד כְּעָן:
@46 כִּדְנַן אֲמַר יְיָ בְּדָא תִדַע אֲרֵי אֲנָא יְיָ הָא אֲנָא מָחֵי בְּחֻטְרָא דִי בִידִי עַל מַיָא דִי בְנַהֲרָא וְיִתְהַפְּכוּן לִדְמָא:
@47 וְנוּנֵי דִי בְנַהֲרָא תְּמוּת וּסְרִי נַהֲרָא וְיִלְאוּן מִצְרָאֵי לְמִשְׁתֵּי מַיָא מִן נַהֲרָא:
@48 וַאֲמַר יְיָ לְמשֶׁה אֱמַר לְאַהֲרֹן טּוֹל חֻטְרָךְ וַאֲרֵים יְדָךְ עַל מַיָא דְמִצְרַיִם עַל נַהֲרֵיהוֹן עַל אֲרִתֵּיהוֹן וְעַל אַגְמֵיהוֹן וְעַל כָּל בֵּית כְּנִישׁוּת מֵימֵיהוֹן וִיהוֹן דְמָא וִיהֵי דְמָא בְּכָל אַרְעָא דְמִצְרַיִם וּבְמָנֵי אָעָא וּבְמָנֵי אַבְנָא:
@49 וַעֲבָדוּ כֵן משֶׁה וְאַהֲרֹן כְּמָא דְפַקֵיד יְיָ וַאֲרֵים בְּחֻטְרָא וּמְחָא יָת מַיָא דִי בְנַהֲרָא לְעֵינֵי פַּרְעֹה וּלְעֵינֵי עַבְדוֹהִי וְאִתְהַפִיכוּ כָּל מַיָא דִי בְנַהֲרָא לִדְמָא:
@50 וְנוּנֵי דִי בְנַהֲרָא מִיתוּ וּסְרִי נַהֲרָא וְלָא יְכִילוּ מִצְרָאֵי לְמִשְׁתֵּי מַיָא מִן נַהֲרָא וַהֲוָה דְמָא בְּכָל אַרְעָא דְמִצְרָיִם:
@51 וַעֲבָדוּ כֵן חָרָשֵׁי מִצְרַיִם בְּלַחֲשֵׁיהוֹן וְאִתַּקַף לִבָּא דְפַרְעֹה וְלָא קַבֵּיל מִנְהוֹן כְּמָא דְמַלִיל יְיָ:
@52 וְאִתְפְּנִי פַרְעֹה וְעַל לְבֵיתֵהּ וְלָא שַׁוִי לִבֵּהּ אַף לְדָא:
@53 וַחֲפָרוּ כָל מִצְרָאֵי סַחֲרָנוּת נַהֲרָא מַיָא לְמִשְׁתֵּי אֲרֵי לָא יְכִילוּ לְמִשְׁתֵּי מִמַיָא דְנַהֲרָא:
@54 וְאַשְׁלֵם שִׁבְעַת יוֹמִין בָּתַר דִמְחָא יְיָ יָת נַהֲרָא:
@55 וַאֲמַר יְיָ לְמשֶׁה עוּל לְוָת פַּרְעֹה וְתֵימַר לֵהּ כִּדְנַן אֲמַר יְיָ שַׁלַח יָת עַמִי וְיִפְלְחוּן קֳדָמָי:
@56 וְאִם סָרִיב אַתְּ לְשַׁלָחָא הָא אֲנָא מָחֵי יָת כָּל תְּחוּמָךְ בְּעֻרְדְעָנַיָא:
@57 וִירַבֵּי נַהֲרָא עֻרְדְעָנַיָא וְיִסְקוּן וְיֶעֱלוּן בְּבֵיתָךְ וּבְאִדְרוֹן בֵּית מִשְׁכְּבָךְ וְעַל עַרְסָךְ וּבְבֵית עַבְדָיךְ וּבְעַמָךְ וּבְתַנוּרָךְ וּבְאַצְוָתָךְ:
@58 וּבָךְ וּבְעַמָךְ וּבְכָל עַבְדָיךְ יִסְקוּן עֻרְדְעָנַיָא:
@59 וַאֲמַר יְיָ לְמשֶׁה אֱמַר לְאַהֲרֹן אֲרֵים יָת יְדָךְ בְּחֻטְּרָךְ עַל נַהֲרַיָא עַל אֲרִיתַּיָא וְעַל אַגְמַיָא וְאַסֵיק יָת עֻרְדְעָנַיָא עַל אַרְעָא דְמִצְרָיִם:
@60 וַאֲרֵים אַהֲרֹן יָת יְדֵהּ עַל מַיָא דְמִצְרָאֵי וּסְלֵיקַת עֻרְדְעָנַיָא וַחֲפַת יָת אַרְעָא דְמִצְרָיִם:
@61 וַעֲבָדוּ כֵן חָרָשַׁיָא בְּלַחֲשֵׁיהוֹן וְאַסִ יקוּ יָת עֻרְדְעָנַיָא עַל אַרְעָא דְמִצְרָיִם:
@62 וּקְרָא פַרְעֹה לְמשֶׁה וּלְאַהֲרֹן וַאֲמַר צַלוֹ קֳדָם יְיָ וְיַעְדֵי עֻרְדְעָנַיָא מִנִי וּמֵעַמִי וְאֶשְׁלַח יָת עַמָא וְיִדְבְּחוּן קֳדָם יְיָ:
@63 וַאֲמַר משֶׁה לְפַרְעֹה שְׁאַל לָךְ גְבוּרָא הַב לִי זְמַן לְאִמָתַי אֱצַלֵי עֲלָךְ וְעַל עַבְדָיךְ וְעַל עַמָךְ לְשֵׁיצָאָה עֻרְדְעָנַיָא מִנָךְ וּמִבָּתָּיךְ לְחוֹד בְּנַהֲרָא תִּשְׁתָּאָרָן:
@64 וַאֲמַר לִמְחָר וַאֲמַר כְּפִתְגָמָךְ בְּדִיל דְתִדַע אֲרֵי לֵית כַּיְיָ אֱלָהָנָא:
@65 וְיֶעְדוּן עֻרְדְעָנַיָא מִנָךְ וּמִבָּתָּיךְ וּמֵעַבְדָיךְ וּמֵעַמָךְ לְחוֹד בְּנַהֲרָא יִשְׁתָּאָרָן:
@66 וּנְפַק משֶׁה וְאַהֲרֹן מִלְוָת פַרְעֹה וְצַלִי משֶׁה קֳדָם יְיָ עַל עֵסַק עֻרְדְעָנַיָא דִי שַׁוִי לְפַרְעֹה:
@67 וַעֲבַד יְיָ כְּפִתְגָמָא דְמשֶׁה וּמִיתוּ עוּרְדְעָנַיָא מִן בָּתַּיָא מִן דָרָתָא וּמִן חַקְלָתָא:
@68 וּכְנָשׁוּ יָתְהוֹן דְגוֹרִין דְגוֹרִין וּסְרִיאוּ עַל אַרְעָא:
@69 וַחֲזָא פַרְעֹה אֲרֵי הֲוַת רְוַחְתָּא וְיִתְיַקַר יָת לִבֵּהּ וְלָא קַבִּיל מִנְהוֹן כְּמָא דְמַלִיל יְיָ:
@70 וַאֲמַר יְיָ לְמשֶׁה אֱמַר לְאַהֲרֹן אֲרֵים יָת חֻטְרָךְ וּמְחָא יָת עַפְרָא דְאַרְעָא וִיהֵא לְקַלְמְתָא בְּכָל אַרְעָא דְמִצְרָיִם:
@71 וַעֲבָדוּ כֵן וַאֲרֵים אַהֲרֹן יָת יְדֵהּ בְחֻטְרֵהּ וּמְחָא יָת עַפְרָא דְאַרְעָא וַהֲוַת קַלְמְתָא בַּאֲנָשָׁא וּבִבְעִירָא כָּל עַפְרָא דְאַרְעָא הֲוַת קַלְמְתָא בְּכָל אַרְעָא דְמִצְרָיִם:
@72 וַעֲבָדוּ כֵן חָרָשַׁיָא בְּלַחֲשֵׁיהוֹן לְאַפָּקָא יָת קַלְמְתָא וְלָא יָכִילוּ וַהֲוַת קַלְמְתָא בַּאֲנָשָׁא וּבִבְעִירָא:
@73 וַאֲמָרוּ חָרָשַּׁיָא לְפַרְעֹה הָא מָחָא מִן קֳדָם יְיָ הִיא וְאִתַּקַף לִבָּא דְפַרְעֹה וְלָא קַבִּיל מִנְהוֹן כְּמָא דִמַלִיל יְיָ:
@74 וַאֲמַר יְיָ לְמשֶׁה אַקְדֵם בְּצַפְרָא וְאִתְעַתַּד קֳדָם פַּרְעֹה הָא נָפֵק לְמַיָא וְתֵימַר לֵהּ כִּדְנַן אֲמַר יְיָ שַׁלַח עַמִי וְיִפְלְחוּן קֳדָמָי:
@75 אֲרֵי אִם לֵיתָךְ מְשַׁלַח יָת עַמִי הָא אֲנָא מַשְׁלַח בָּךְ וּבְעַבְדָיךְ וּבְעַמָךְ וּבְבָתָּיךְ יָת עָרוֹבָא וְיִמְלוּן בָּתֵּי מִצְרַיִם יָת עָרוֹבָא וְאַף אַרְעָא דְאִנוּן עֲלַהּ:
@76 וְאַפְרֵישׁ בְּיוֹמָא הַהוּא יָת אַרְעָא דְגשֶׁן דְעַמִי קָאִים עֲלַהּ בְּדִיל דְלָא לְמֶהֱוֵי תַמָן עָרוֹבָא בְּדִיל דְתִדַע אֲרֵי אֲנָא יְיָ שַׁלִיטּ בְּגוֹ אַרְעָא:
@77 וֶאֱשַׁוֵי פוּרְקַן לְעַמִי וְעַל עַמָךְ אַיְתִי מָחָא לִמְחָר יְהֵא אָתָא הָדֵין:
@78 וַעֲבַד יְיָ כֵּן וַאֲתָא עָרוֹבָא תַקִיף לְבֵית פַּרְעֹה וּלְבֵית עַבְּדוֹהִי וּבְכָל אַרְעָא דְמִצְרַיִם אִתְחַבָּלַת אַרְעָא מִן קֳדָם עָרוֹבָא:
@79 וּקְרָא פַרְעֹה לְמשֶׁה וּלְאַהֲרֹן וַאֲמַר אֱזִילוּ דַבָּחוּ קֳדָם אֱלָהָכוֹן בְּאַרְעָא:
@80 וַאֲמַר משֶׁה לָא תַקֵן לְמֶעְבַּד כֵּן אֲרֵי בְעִירָא דְמִצְרָאֵי דָחֲלִין לֵהּ מִנֵהּ אֲנַחְנָא נָסְבִין לְדַבָּחָא קֳדָם יְיָ אֱלָהָנָא הָא נְדַבַּח יָת בְּעִירָא דְמִצְרָאֵי דָחֲלִין לֵהּ וְאִנוּן יְהוֹן חָזָן הֲלָא יֵימְרוּן לְמִרְגְמָנָא:
@81 מַהֲלַךְ תְּלָתָא יוֹמִין נֵיזִיל בְּמַדְבְּרָא וּנְדַבַּח קֳדָם יְיָ אֱלָהָנָא כְּמָא דְיֵימַר לָנָא:
@82 וַאֲמַר פַּרְעֹה אֲנָא אֲשַׁלַח יָתְכוֹן וְתִדְבְּחוּן קֳדָם יְיָ אֱלָהָכוֹן בְּמַדְבְּרָא לְחוֹד אַרְחָקָא לָא תְרַחֲקוּן לְמֵיזַל צַלוֹ אַף עָלָי:
@83 וַאֲמַר משֶׁה הָא אֲנָא נָפֵק מֵעִמָךְ וֶאֱצַלֵי קֳדָם יְיָ וְיַעְדֵי עָרוֹבָא מִפַּרְעֹה מֵעַבְדוֹהִי וּמֵעַמֵהּ מְחָר לְחוֹד לָא יוֹסֵף פַּרְעֹה לְשַׁקָרָא בְּדִיל דְלָא לְשַׁלָחָא יָת עַמָא לְדַבָּחָא קֳדָם יְיָ:
@84 וּנְפַק משֶׁה מִן קֳדָם פַּרְעֹה וְצַלִי קֳדָם יְיָ:
@85 וַעֲבַד יְיָ כְּפִתְגָמָא דְמשֶׁה וְאַעְדִי עָרוֹבָא מִפַּרְעֹה מֵעַבְדוֹהִי וּמֵעַמֵהּ לָא אִשְׁתָּאַר חָד:
@86 וְיַקַר פַּרְעֹה יָת לִבֵּהּ אַף בְּזִמְנָא הָדָא וְלָא שַׁלַח יָת עַמָא:
@87 וַאֲמַר יְיָ לְמשֶׁה עוּל לְוָת פַּרְעֹה וּתְמַלֵל עִמֵהּ כִּדְנַן אֲמַר יְיָ אֱלָהָא דִיהוּדָאֵי שַׁלַח יָת עַמִי וְיִפְלְחוּן קֳדָמָי:
@88 אֲרֵי אִם סָרִיב אַתְּ לְשַׁלָחָא וְעַד כְּעַן אַתְּ מַתְקֵף בְּהוֹן:
@89 הָא מָחָא מִן קֳדָם יְיָ הַוְיָא בִּבְעִירָךְ דִי בְחַקְלָא בְּסוּסְוָתָא בַּחֲמָרֵי בְּגַמְלֵי בְּתוֹרֵי וּבְעָנָא מוֹתָא תַּקִיף לַחֲדָא:
@90 וְאַפְרֵישׁ יְיָ בֵּין בְּעִירָא דְיִשְׂרָאֵל וּבֵין בְּעִירָא דְמִצְרָיִם וְלָא יְמוּת מִכָּל לִבְנֵי יִשְׂרָאֵל מִדָעַם:
@91 וְשַׁוִי יְיָ זִמְנָא לְמֵימָר מְחַר יַעְבֵּד יְיָ פִּתְגָמָא הָדֵין בְּאַרְעָא:
@92 וַעֲבַד יְיָ יָת פִּתְגָמָא הָדֵין בְּיוֹמָא דְבַתְרוֹהִי וּמִית כֹּל בְּעִירָא דְמִצְרָיִם וּמִבְּעִירָא דִבְנֵי יִשְׂרָאֵל לָא מִית חָד:
@93 וּשְׁלַח פַּרְעֹה וְהָא לָא מִית מִבְּעִירָא דְיִשְׂרָאֵל עַד חָד וְאִתְיַקַר לִבָּא דְפַרְעֹה וְלָא שַׁלַח יָת עַמָא:
@94 וַאֲמַר יְיָ לְמשֶׁה וּלְאַהֲרֹן סִיבוּ לְכוֹן מְלֵי חָפְנֵיכוֹן פִּיחָא דְאַתּוּנָא וְיִזְרְקִנֵהּ משֶׁה לְצֵית שְׁמַיָא לְעֵינֵי פַרְעֹה:
@95 וִיהֵי לְאַבְקָא עַל כָּל אַרְעָא דְמִצְרָיִם וִיהֵי עַל אֲנָשָׁא וְעַל בְּעִירָא לְשִׁיחֲנָא סַגִי אֲבַעְבֻּעִין בְּכָל אַרְעָא דְמִצְרָיִם:
@96 וּנְסִיבוּ יָת פִּיחָא דְאַתּוּנָא וְקָמוּ קֳדָם פַּרְעֹה וּזְרַק יָתֵהּ משֶׁה לְצֵית שְׁמַיָא וַהֲוָה שִׁיחֲנָא אֲבַעְבֻּעִין סָגֵי בַּאֲנָשָׁא וּבִבְעִירָא:
@97 וְלָא יָכִילוּ חָרָשַׁיָא לְמֵיקַם קֳדָם משֶׁה מִן קֳדָם שִׁיחֲנָא אֲרֵי הֲוָה שִׁיחֲנָא בְּחָרָשַׁיָא וּבְכָל מִצְרָאֵי:
@98 וְתַקִיף יְיָ יָת לִבָּא דְפַרְעֹה וְלָא קַבִּיל מִנְהוֹן כְּמָא דְמַלֵיל יְיָ עִם משֶׁה:
@99 וַאֲמַר יְיָ לְמשֶׁה אַקְדֵם בְּצַפְרָא וְאִתְעַתַּד קֳדָם פַּרְעֹה וְתֵימַר לֵהּ כִּדְנַן אֲמַר יְיָ אֱלָהָא דִיהוּדָאֵי שַׁלַח יָת עַמִי וְיִפְלְחוּן קֳדָמָי:
@100 אֲרֵי בְּזִמְנָא הָדָא אֲנָא שָׁלַח יָת כָּל מְחָתַי לְלִבָּךְ וּבְעַבְדָיךְ וּבְעַמָךְ בְּדִיל דְתִדַע אֲרֵי לֵית דִכְוָתִי שַׁלִיט בְּכָל אַרְעָא:
@101 אֲרֵי כְעַן קְרֵיב קֳדָמַי דְאֶשְׁלַח פּוֹן יָת מַחַת גְבֻרְתִּי וְאֶמְחֵי יָתָךְ וְיָת עַמָךְ בְּמוֹתָא וְשֵׁיצִיאַת מִן אַרְעָא:
@102 וּבְרַם בְּדִיל דָא קַיֵמְתָּךְ בְּדִיל לְאַחֲזָיוּתָךְ יָת חֵילִי וּבְדִיל דִיהוֹן מִשְׁתָּעַן גְבוּרַת שְׁמִי בְּכָל אַרְעָא:
@103 עַד כְּעַן אַתְּ כְּבֵישַׁת בֵּהּ בְּעַמִי בְּדִיל דְלָא לְשַׁלָחוּתְהוֹן:
@104 הָא אֲנָא מָחֵית מִטְרָא בְּעִדָנָא הָדֵין מְחַר בַּרְדָא תַּקִיף לַחֲדָא דִי לָא הֲוָה דִכְוָתֵהּ בְּמִצְרַיִם לְמִן יוֹמָא דְאִשְׁתַּכְלָלַת וְעַד כְּעָן:
@105 וּכְעַן שְׁלַח כְּנוֹשׁ יָת בְּעִירָךְ וְיָת כָּל דִי לָךְ בְּחַקְלָא כָּל אֲנָשָׁא וּבְעִירָא דְאִשְׁתְּכַח בְּחַקְלָא וְלָא יִתְכְּנֵשׁ לְבֵיתָא וְיֵחוֹת עֲלֵיהוֹן בַּרְדָא וִימוּתוּן:
@106 דְדָחִיל מִפִּתְגָמָא דַיְיָ מֵעַבְדֵי פַּרְעֹה כְּנַשׁ יָת עַבְדוֹהִי וְיָת גֵיתוֹהִי לְבָתַּיָא:
@107 וְדִי לָא שַׁוִי לִבֵּהּ לְפִתְגָמָא דַיְיָ שְׁבַק יָת עַבְדוֹהִי וְיָת גֵיתוֹהִי בְּחַקְלָא:
@108 וַאֲמַר יְיָ לְמשֶׁה אֲרֵים יָת יְדָךְ עַל צֵית שְׁמַיָא וִיהֵי בַרְדָא בְּכָל אַרְעָא דְמִצְרָאֵי עַל אֲנָשָׁא וְעַל בְּעִירָא וְעַל כָּל עֶסְבָּא דְחַקְלָא בְּאַרְעָא דְמִצְרָיִם:
@109 וַאֲרֵים משֶׁה יָת חֻטְרֵהּ עַל צֵית שְׁמַיָא וַיְיָ יְהַב קָלִין וּבַרְדָא וּמְהַלְכָא אֶשָׁתָא עַל אַרְעָא וְאַמְטַר יְיָ בַּרְדָא עַל אַרְעָא דְמִצְרָיִם:
@110 וַהֲוָה בַרְדָא וְאֶשָׁתָא מִשְׁתַּלְהָבַת בְּגוֹ בַרְדָא תַּקִיף לַחֲדָא דִי לָא הֲוָה דִכְוָתֵהּ בְּכָל אַרְעָא דְמִצְרַיִם מֵעִדַן דַהֲוַת לְעָם:
@111 וּמְחָא בַרְדָא בְּכָל אַרְעָא דְמִצְרַיִם יָת כָּל דִי בְחַקְלָא מֵאֲנָשָׁא וְעַד בְּעִירָא וְיָת כָּל עֶסְבָּא דְחַקְלָא מְחָא בַרְדָא וְיָת כָּל אִילַן דִבְחַקְלָא תְּבַר:
@112 לְחוֹד בְּאַרְעָא דְגשֶׁן דִי תַמָן בְּנֵי יִשְׂרָאֵל לָא הֲוָה בַּרְדָא:
@113 וּשְׁלַח פַּרְעֹה וּקְרָא לְמשֶׁה וּלְאַהֲרֹן וַאֲמַר לְהוֹן חָבִית זִמְנָא הָדָא יְיָ זַכָּאָה וַאֲנָא וְעַמִי חַיָבִין:
@114 צַלוֹ קֳדָם יְיָ וְסַגִי קֳדָמוֹהִי רְוַח דְלָא יְהוֹן עֲלָנָא קָלִין דִלְוַט כְּאִלֵין מִן קֳדָם יְיָ וּבַרְדָא וְאֶשְׁלַח יָתְכוֹן וְלָא תוֹסְפוּן לְאִתְעַכָּבָא:
@115 וַאֲמַר לֵהּ משֶׁה כְּמִפְּקִי מִן קַרְתָּא אֶפְרוֹשׂ יְדַי בִּצְלוֹ קֳדָם יְיָ קָלַיָא יִתְמַנְעוּן וּבַרְדָא לָא יְהֵי עוֹד בְּדִיל דְתִדַע אֲרֵי דַיְיָ אַרְעָא:
@116 וְאַתְּ וְעַבְדָיךְ יְדַעְנָא אֲרֵי עַד כְּעַן לָא אִתְכְּנַעְתּוּן מִן קֳדָם יְיָ אֱלֹהִים:
@117 וְכִתָּנָא וְסַעֲרֵי לְקוֹ אֲרֵי סַעְרַנְיָא אַבִּיבִין וְכִתָּנָא גַבְעוֹלִין:
@118 וְחִטָאָה וְכֻנְתַּיָא לָא לְקוֹ אֲרֵי אֲפֵילָתָא אִנוּן:
@119 וּנְפַק משֶׁה מִלְוַת פַּרְעֹה יָת קַרְתָּא וּפְרַשׂ יְדוֹהִי בִּצְלוֹ קֳדָם יְיָ וַיִתְמַנְעוּן קָלַיָא וּבַרְדָא וּמִטְרָא דַהֲוָה נָחִית לָא מְטָא עַל אַרְעָא:
@120 וַחֲזָא פַרְעֹה אֲרֵי אִתְמְנַע מִטְרָא וּבַרְדָא וְקָלַיָא וְאוֹסֵף לְמֶחֱטֵי וְיַקְרֵהּ לְלִבֵּהּ הוּא וְעַבְדוֹהִי:
@121 וְאִתַּקַף לִבָּא דְפַרְעֹה וְלָא שַׁלַח יָת בְּנֵי יִשְׂרָאֵל כְּמָא דִי מַלֵיל יְיָ בִּידָא דְמשֶׁה: פפפ:

@1 **וידבר אלהים אל משה.** דבר אתו משפט על שהקשה לדבר ולומר (לעיל ה כב) למה הרעותה לעם הזה: ויאמר אליו אני ה'. נאמן לשלם שכר טוב למתהלכים לפני. ולא לחנם שלחתיך כי אם לקים דברי שדברתי לאבות הראשונים. ובלשון הזה מצינו שהוא נדרש בכמה מקומות אני ה' נאמן לפרע, כשהוא אמור אצל עונש, כגון (ויקרא יט יב) וחללת את שם אלהיך אני ה', וכשהוא אמור אצל קיום מצות, כגון (ויקרא כב לא) ושמרתם מצותי ועשיתם אותם אני ה', נאמן לתן שכר:
@2 **וארא.** אל האבות: **באל שדי.** הבטחתים הבטחות ובכלן אמרתי להם אני אל שדי: **ושמי ה' לא נודעתי להם.** לא הודעתי אין כתיב כאן אלא לא נודעתי לא נכרתי להם במדת אמתות שלי שעליה נקרא שמי ה' נאמן לאמת דברי, שהרי הבטחתים ולא קימתי:
@3 **וגם הקמתי את בריתי** וגו' **.** וגם כשנראיתי להם באל שדי הצבתי והעמדתי בריתי ביני וביניהם: **לתת להם את ארץ כנען.** לאברהם בפרשת מילה נאמר (בראשית יז א) אני אל שדי וגו' , (בראשית יז ח) ונתתי לך ולזרעך אחריך את ארץ מגוריך, ליצחק (בראשית כו ג) כי לך ולזרעך אתן את כל הארצות האל והקימותי את השבועה אשר נשבעתי לאברהם, ואותה שבועה שנשבעתי לאברהם באל שדי, אמרתי ליעקב (בראשית לה יא. יב) אני אל שדי פרה ורבה וגו' ואת הארץ אשר וגו' , הרי שנדרתי להם ולא קימתי:
@4 **וגם אני.** כמו שהצבתי והעמדתי הברית יש עלי לקים, לפיכך שמעתי את נאקת בני ישראל הנואקים: **אשר מצרים מעבדים אתם ואזכר.** אותו הברית. כי בברית בין הבתרים אמרתי לו (בראשית טו יד) וגם את הגוי אשר יעבדו דן אנכי:
@5 **לכן.** על פי אותה השבועה: **אמר לבני ישראל אני ה'.** הנאמן בהבטחתי: **והוצאתי אתכם.** כי כן הבטחתיו (שם שם) ואחרי כן יצאו ברכוש גדול: **סבלת מצרים.** טורח משא מצרים:
@7 **נשאתי את ידי.** הרימותיה להשבע בכסאי:
@8 **ולא שמעו אל משה.** לא קבלו תנחומין: **מקצר רוח.** כל מי שהוא מצר, רוחו ונשימתו קצרה ואינו יכול להאריך בנשימתו. קרוב לענין זה שמעתי פרשה זו מרבי ברוך ברבי אליעזר, והביא לי ראיה ממקרא זה (ישעיה טז כא) בפעם הזאת אודיעם את ידי ואת גבורתי וידעו כי שמי ה', למדנו כשהקדוש ברוך הוא מאמן את דבריו אפילו לפרענות מודיע ששמו ה', וכל שכן האמנה לטובה. ורבותינו דרשוהו לענין שלמעלה, שאמר משה (לעיל ה כב) למה הרעתה, אמר לו הקדוש ברוך הוא חבל על דאבדין ולא משתכחין. יש לי להתאונן על מיתת האבות, הרבה פעמים נגליתי אליהם באל שדי ולא אמרו לי מה שמך, ואתה אמרת (לעיל ג יג) מה שמו מה אומר אליהם: **וגם הקמתי** וגו' **.** וכשבקש אברהם לקבור את שרה לא מצא קבר עד שקנה בדמים מרבים, וכן ביצחק ערערו עליו על הבארות אשר חפר, וכן ביעקב (בראשית לג יט) ויקן את חלקת השדה, לנטות אהלו, ולא הרהרו אחר מדותי, ואתה אמרת (ה כב) למה הרעתה. ואין המדרש מתישב אחר המקרא מפני כמה דברים אחת, שלא נאמר, ושמי ה' לא שאלו לי. ואם תאמר לא הודיעם שכך שמו, הרי תחלה כשנגלה לאברהם בין הבתרים נאמר (בראשית טו ז) אני ה' אשר הוצאתיך מאור כשדים. ועוד, היאך הסמיכה נמשכת בדברים שהוא סומך לכאן (פסוק ה) וגם אני שמעתי וגו' (פסוק ו) לכן אמר לבני ישראל. לכך אני אומר יתישב המקרא על פשוטו דבר דבור על אפניו, והדרשה תדרש, שנאמר (ירמיה כג כט) הלוא כה דברי כאש נאם ה' וכפטיש יפוצץ סלע, מתחלק לכמה ניצוצות:
@11 **ואיך ישמעני פרעה.** זה אחד מעשרה קל וחמר שבתורה: **ערל שפתים.** אטום שפתים. וכן כל לשון ערלה אני אומר שהוא אטום (ירמיה ו י) ערלה אזנם, אטומה משמוע, (ירמיה ט כה) ערלי לב, אטומים מהבין, (חבקוק ב טז) שתה גם אתה והערל, והאטם משכרות כוס הקללה. ערלת בשר, שהגיד אטום ומכסה בה. (ויקרא יט כג) וערלתם ערלתו, עשו לו אטם וכסוי אסור שיבדיל בפני אכילתו, (שם) שלש שנים יהיה לכם ערלים, אטום ומכסה ומבדל מלאכלו:
@12 **וידבר ה' אל משה ואל אהרן.** לפי שאמר משה (פסוק יב) ואני ערל שפתים, צירף לו הקדוש ברוך הוא את אהרן להיות לו לפה ולמליץ: **ויצום אל בני ישראל.** צום עליהם להנהיגם בנחת ולסבול אותם: **ואל פרעה מלך מצרים.** צום עליו לחלק לו כבוד בדבריהם, זהו מדרשו. ופשוטו צום על דבר ישראל ועל שליחותו אל פרעה. ודבר הצווי מהו, מפורש בפרשה שניה לאחר סדר היחס, אלא מתוך שהזכיר משה ואהרן הפסיק הענין באלה ראשי בית אבותם (פסוק יד) ללמדנו היאך נלדו משה ואהרן ובמי נתיחסו:
@13 **אלה ראשי בית אבתם.** מתוך שהזקק ליחס שבטו של לוי עד משה ואהרן, בשביל משה ואהרן התחיל ליחסם דרך תולדותם מראובן. [ובפסיקתא רבתי ראיתי לפי שקנטרם יעקב אביהם לשלשה שבטים הללו בשעת מותו, חזר הכתוב ויחסם כאן לבדם לומר שחשובים הם] :
@15 **ושני חיי לוי** וגו' **.** למה נמנו שנותיו של לוי, להודיע כמה ימי השעבוד, שכל זמן שאחד מן השבטים קים לא היה שעבוד, שנאמר (שמות א ו) וימת יוסף וכל אחיו, ואחר כך (שם ח) ויקם מלך חדש, ולוי האריך ימים על כלם:
@17 **ושני חיי קהת ושני חיי עמרם** וגו' **.** מחשבון זה אנו למדים על מושב בני ישראל ארבע מאות שנה שאמר הכתוב, שלא בארץ מצרים לבדה היו, אלא מיום שנלד יצחק, שהרי קהת מיורדי מצרים היה, חשוב כל שנותיו ושנות עמרם ושמונים של משה לא תמצאם ארבע מאות שנה, והרבה שנים נבלעים לבנים בשני האבות:
@19 **יוכבד דדתו.** אחת אבוהי בת לוי אחות קהת:
@22 **אחות נחשון.** מכאן למדנו הנושא אשה צריך לבדוק באחיה:
@24 **מבנות פוטיאל.** מזרע יתרו שפטם עגלים לעבודה זרה. ומזרע יוסף שפטפט ביצרו:
@25 **הוא אהרן ומשה.** אלו שהזכרו למעלה, שילדה יוכבד לעמרם, הוא אהרן ומשה. יש מקומות שמקדים אהרן למשה ויש מקומות שמקדים משה לאהרן, לומר לך ששקולין כאחד: **על צבאתם.** בצבאותם, כל צבאם לשבטיהם. יש על שאינו אלא במקום אות אחת (בראשית כז מ) ועל חרבך תחיה, כמו בחרבך, (יחזקאל לג כו) עמדתם על חרבכם, כמו בחרבכם:
@26 **הם המדברים** וגו' **.** הם שנצטוו הם שקימו: **הוא משה ואהרן.** הם בשליחותם ובצדקתם מתחלה ועד סוף:
@27 **ויהי ביום דבר** וגו' **.** מחבר למקרא שלאחריו:
@28 **וידבר ה'.** הוא הדבור עצמו האמור למעלה (פסוק יא) בא דבר אל פרעה מלך מצרים, אלא מתוך שהפסיק הענין כדי ליחסם, חזר הענין עליו להתחיל בו: **אני ה'.** כדאי אני לשלחך ולקים דברי שליחותי:
@29 **ויאמר משה לפני ה'.** היא האמירה שאמר למעלה (פסוק יב) הן בני ישראל לא שמעו אלי, ושנה הכתוב כאן כיון שהפסיק הענין, וכך היא השטה כאדם האומר נחזור על הראשונות:
@30 **נתתיך אלהים לפרעה.** שופט ורודה לרדותו במכות ויסורין: **יהיה נביאך.** כתרגומו מתורגמנך, וכן כל לשון נבואה אדם המכריז ומשמיע לעם דברי תוכחות, והוא מגזרת (ישעיה נז יט) ניב שפתים, (משלי י לא) ינוב חכמה, ויכל מהתנבות דשמואל (א' י יג) . ובלעז קוראין לו פרקייר''א :
@31 **אתה תדבר.** פעם אחת כל שליחות ושליחות כפי ששמעתו מפי, ואהרן אחיך ימליצנו ויטעימנו באזני פרעה:
@32 **ואני אקשה.** מאחר שהרשיע והתריס כנגדי, וגלוי לפני שאין נחת רוח באמות עובדי עבודה זרה לתת לב שלם לשוב, טוב לי שיתקשה לבו למען הרבות בו אותותי ותכירו אתם את גבורותי. וכן מדתו של הקדוש ברוך הוא מביא פרענות על האמות עובדי עבודה זרה כדי שישמעו ישראל וייראו, שנאמר (צפניה ג ו) הכרתי גוים נשמו פנותם וגו' , (שם ז) אמרתי אך תיראי אותי תקחי מוסר, ואף על פי כן בחמש מכות הראשונות לא נאמר ויחזק ה' את לב פרעה, אלא ויחזק לב פרעה:
@34 **את ידי.** יד ממש להכות בהם:
@38 **מופת.** אות, להודיע שיש צורך (צרוך) במי ששולח אתכם: **לתנין.** נחש:
@40 **בלהטיהם.** בלחשיהון ואין לו דמיון במקרא, ויש לדמות לו (בראשית ג כב) להט החרב המתהפכת, דומה שהיא מתהפכת על ידי לחש:
@41 **ויבלע מטה אהרן.** מאחר שחזר ונעשה מטה בלע את כלן:
@43 **כבד.** תרגומו יקיר, ולא אתיקר, מפני שהוא שם דבר, כמו (שמות יח יח) כי כבד ממך הדבר:
@44 **הנה יצא המימה.** לנקביו, שהיה עושה עצמו אלוה ואומר שאינו צריך לנקביו ומשכים ויוצא לנילוס ועושה שם צרכיו:
@45 **עד כה.** עד הנה ומדרשו עד שתשמע ממני מכת בכורות, שאפתח בה בכה (יא ד) כה אמר ה' כחצות הלילה:
@46 **ונהפכו לדם.** לפי שאין גשמים יורדים במצרים, ונילוס עולה ומשקה את הארץ, ומצרים עובדים לנילוס, לפיכך הלקה את יראתם ואחר כך הלקה אותם:
@47 **ונלאו מצרים.** לבקש רפואה למי היאור שיהיו ראוין לשתות:
@48 **אמר אל אהרן.** לפי שהגין היאור על משה כשנשלך לתוכו, לפיכך לא לקה על ידו לא בדם ולא בצפרדעים, ולקה על ידי אהרן: **נהרתם.** הם נהרות המושכים כעין נהרות שלנו: **יאריהם.** הם ברכות נגרים העשויות בידי אדם משפת הנהר לשדות, ונילוס מימיו מתברכים ועולה דרך היאורים ומשקה השדות: **אגמיהם.** קבוצת מים שאינן נובעין ואינן מושכין, אלא עומדין במקום אחד, וקורין לו אישטנ''ק : **בכל ארץ מצרים.** אף במרחצאות ובאמבטאות שבבתים: **ובעצים ובאבנים.** מים שבכלי עץ ובכלי אבן:
@51 **בלטיהם.** לחש שאומרין אותו בלט ובחשאי. ורבותינו אמרו בלטיהם מעשה שדים, בלהטיהם מעשה כשפים: **ויחזק לב פרעה.** לומר על ידי מכשפות אתם עושים כן, תבן אתם מכניסין לעפריים, עיר שכלה תבן, אף אתם מביאין מכשפות למצרים שכלה כשפים:
@52 **גם לזאת.** למופת המטה, שנהפך לתנין ולא לזה של דם:
@54 **וימלא.** מנין שבעת ימים, שלא שב היאור לקדמותו, שהיתה המכה משמשת רביע חדש ושלשה חלקים היה מעיד ומתרה בהם:
@56 **ואם מאן אתה.** ואם סרבן אתה. מאן כמו ממאן, מסרב, אלא כנה האדם על שם המפעל, כמו (איוב טז יב) שלו, (ירמיה מח יא) ושקט, (מלכים א' כ מג) סר וזעף: **נגף את כל גבולך.** מכה, וכן כל לשון מגפה אינו לשון מיתה אלא לשון מכה, וכן (שמות כא כב) ונגפו אשה הרה, אינו לשון מיתה. וכן (ירמיה יג טז) ובטרם יתנגפו רגליכם, (תהלים צא יב) פן תגוף באבן רגלך, (ישעיה ח יד) ולאבן נגף:
@57 **ועלו.** מן היאור: **בביתך.** ואחר כך בבתי עבדיך. הוא התחיל בעצה תחלה (שמות א ט) ויאמר אל עמו, וממנו התחילה הפרענות:
@58 **ובכה ובעמך.** בתוך מעיהם נכנסין ומקרקרין:
@60 **ותעל הצפרדע.** צפרדע אחת היתה והיו מכין אותה והיא מתזת נחילים נחילים זהו מדרשו. ופשוטו יש לומר שרוץ הצפרדעים קורא לשון יחידות. וכן (להלן יד) ותהי הכנם, הרחישה דוילייר''א בלעז , ואף ותעל הצפרדע גרינוילייר''א בלעז [רחישת צפרדעים] :
@63 **התפאר עלי.** כמו (ישעיה י טו) היתפאר הגרזן על החצב בו, משתבח לומר אני גדול ממך ונט''ר בלעז [להתפאר] . וכן התפאר עלי, השתבח להתחכם ולשאול דבר גדול ולומר שלא אוכל לעשותו: **למתי אעתיר לך.** את אשר אעתיר לך היום על הכרתת הצפרדעים, למתי תרצה שיכרתו, ותראה אם אשלים דברי למועד שתקבע לי. אלו נאמר מתי אעתיר, היה משמע מתי אתפלל, עכשיו שנאמר למתי משמע אני היום אתפלל עליך שיכרתו הצפרדעים לזמן שתקבע עלי, אמור לאיזה יום תרצה שיכרתו. אעתיר, העתירו, והעתרתי, ולא נאמר אעתר עתרו ועתרתי, מפני שכל לשון עתר הרבות פלל הוא, וכאשר יאמר הרבו, ארבה, והרביתי לשון מפעיל, כך יאמר, אעתיר, העתירו, והעתרתי דברים, ואב לכלם והעתרתם עלי דבריכם (יחזקאל לה יג) , הרביתם:
@64 **ויאמר למחר.** התפלל היום שיכרתו למחר:
@66 **ויצא ויצעק.** מיד שיכרתו למחר:
@68 **חמרם חמרם.** צבורים צבורים כתרגומו דגורין גלים:
@69 **והכבד את לבו.** לשון פעול הוא, כמו (בראשית יב ט) הלוך ונסוע' וכן (מלכים ב' ג כד) והכות את מואב, (שמו''א כב יג) ושאול לו באלהים, (מלכים א' כ לז) הכה ופצע: **כאשר דבר ה'.** והיכן דבר (שמות ז ד) ולא ישמע אליכם פרעה:
@70 **אמר אל אהרן.** לא היה העפר כדאי ללקות על ידי משה לפי שהגין עליו כשהרג את המצרי ויטמנהו בחול ולקה על ידי אהרן:
@71 **ותהי הכנם.** הרחישה דולייר''א בלעז [רחישת כנים] :
@72 **להוציא את הכנים.** לבראתם ממקום אחר: **ולא יכלו.** שאין השד שולט על בריה פחותה מכשעורה:
@73 **אצבע אלהים הוא.** מכה זו אינה על ידי כשפים, מאת המקום היא: **כאשר דבר ה'.** (ז ד) ולא ישמע אליכם פרעה:
@75 **משליח בך.** מגרה בך, וכן (דברים לב כד) ושן בהמות אשלח בם, לשון שסוי אינציטי''ר בלעז : **את הערב.** כל מיני חיות רעות ונחשים ועקרבים בערבוביא והיו משחיתים בהם. ויש טעם בדבר באגדה בכל מכה ומכה למה זו ולמה זו. בטכסיסי מלחמות מלכים בא עליהם, כסדר מלכות כשצרה על עיר, בתחלה מקלקל מעינותיה, ואחר כך תוקעין עליהם ומריעין בשופרות ליראם ולבהלם, וכן הצפרדעים מקרקרים והומים וכו. כדאיתא במדרש רבי תנחומא:
@76 **והפליתי.** והפרשתי, וכן (שמות ט ד) והפלה ה', וכן (דברים ל יא) לא נפלאת היא ממך. לא מבדלת ומפרשת היא ממך: **למען תדע כי אני ה' בקרב הארץ.** אף על פי ששכינתי בשמים גזרתי מתקימת בתחתונים:
@77 **ושמתי פדת.** שיבדיל בין עמי ובין עמך:
@78 **תשחת הארץ.** נשחתה הארץ. אתחבלת ארעא:
@79 **זבחו לאלהיכם בארץ.** במקומכם, ולא תלכו במדבר:
@80 **תועבת מצרים.** יראת מצרים, כמו (מלכים ב' כג יג) ולמלכם תועבת בני עמון, ואצל ישראל קורא אותה תועבה. ועוד יש לומר בלשון אחר תועבת מצרים, דבר שנאוי הוא למצרים זביחה שאנו זובחים, שהרי יראתם אנו זובחים: **ולא יסקלנו.** בתמיהה:
@83 **התל.** כמו להתל:
@84 **ויעתר אל ה'.** נתאמץ בתפלה, וכן אם בא לומר, ויעתיר היה יכול לומר ומשמע וירבה בתפלה, וכשהוא אומר בלשון ויפעל משמע וירבה להתפלל:
@85 **ויסר הערב.** ולא מתו כמו שמתו הצפרדעים, שאם מתו היה להם הנאה בעורות:
@86 **גם בפעם הזאת.** אף על פי שאמר (פסוק כד) אנכי אשלח אתכם, לא קים הבטחתו:
@88 **מחזיק בם.** אוחז בם, כמו (דברים כה יא) והחזיקה במבשיו:
@89 **הנה יד ה' הויה.** לשון הוה, כי כן יאמר בלשון נקבה על שעבר היתה ועל העתיד תהיה ועל העומד הויה, כמו עושה, רוצה, רועה:
@90 **והפלה.** והבדיל:
@94 **מלא חפניכם.** ילויני''ש בלעז : **פיח כבשן.** דבר הנפח מן הגחלים עמומים הנשרפים בכבשן, ובלעז אולבי''ש . פיח לשון הפחה, שהרוח מפיחן ומפריחן: **וזרקו משה.** כל דבר הנזרק בכח אינו נזרק אלא ביד אחת. הרי נסים הרבה, אחד שהחזיק קמצו של משה מלא חפנים שלו ושל אהרן. ואחד שהלך האבק על כל ארץ מצרים:
@95 **לשחין פרח אבעבעת.** כתרגומו לשחין סגי אבעבועין, שעל ידו צומחין בהן בועות: **שחין.** לשון חמימות. והרבה יש בלשון משנה (יומא נג ב) שנה שחונה:
@96 **באדם ובבהמה.** ואם תאמר מאין היו להם הבהמות והלא כבר נאמר (פסוק ו) וימת כל מקנה מצרים, אלא לא נגזרה גזרה אלא על אותן שבשדות בלבד, שנאמר (פסוק ג) במקנך אשר בשדה והירא את דבר ה' הניס את מקנהו אל הבתים. וכן שנויה במכילתא אצל (יד ז) ויקח שש מאות רכב בחור:
@100 **את כל מגפתי.** למדנו מכאן שמכת בכורות (י''ג: בכורות) שקולה כנגד כל המכות:
@101 **כי עתה שלחתי את ידי** וגו' **.** כי אלו רציתי כשהיתה ידי במקנך שהכיתים בדבר שלחתיה והכיתי אותך ואת עמך עם הבהמות ותכחד מן הארץ, אבל בעבור זאת העמדתיך וגו' :
@103 **עודך מסתולל בעמי.** כתרגומו כבישת ליה לעמי, והוא מגזרת (ישעיה יא טז) מסלה, דמתרגמינן אורח כבישא, ובלעז קלקיי''ר . וכבר פרשתי בסוף ויהי מקץ כל תבה שתחלת יסודה סמ''ך והיא באה לדבר בלשון מתפעל, נותן התי''ו של שמוש באמצע אותיות של עיקר, כגון זו וכגון (קהלת יב ה) ויסתבל החגב, מגזרת סבל, (במדבר טז יג) כי תשתרר עלינו, מגזרת שר ונגיד, (דניאל ז ח) משתכל הוית:
@104 **כעת מחר.** כעת הזאת למחר, שרט לו שריטה בכותל למחר כשתגיע חמה לכאן ירד הברד: **הוסדה.** שנתיסדה וכל תבה שתחלת יסודה יו''ד כגון יסד, ילד, ידע, יסר, כשהיא מתפעלת תבא הוי''ו במקום היו''ד, כמו הוסדה (הושע ב ה) הולדה (אסתר ב כה) ויודע (בראשית מו כ) ויולד ליוסף, בדברים לא יוסר עבד (משלי כט יט) :
@105 **שלח העז.** כתרגומו שלח כנוש. וכן (ישעיה י לא) ישבי הגבים העיזו, (ירמיה ו א) העזו בני בנימן: **ולא יאסף הביתה.** לשון הכנסה הוא:
@106 **הניס.** הבריח לשון (שמות ד ג) וינס משה:
@108 **על השמים.** לצד השמים, ומדרש אגדה הגביהו הקדוש ברוך הוא למשה למעלה מן השמים:
@110 **מתלקחת בתוך הברד.** נס בתוך נס, האש והברד מעורבין, והברד מים הוא, ולעשות רצון קונם עשו שלום ביניהם:
@114 **ורב.** די לו במה שהוריד כבר:
@115 **כצאתי את העיר.** מן העיר, אבל בתוך העיר לא התפלל, לפי שהיתה מלאה גלולים:
@116 **טרם תיראון.** עדין לא תיראון. וכן כל טרם שבמקרא עדין לא הוא, ואינו לשון קודם, כמו (בראשית יט ד) טרם ישכבו, עד לא שכיבו (שם ב ה) טרם יצמח, עד לא צמח, אף זה כן הוא ידעתי כי עדין אינכם יראים ומשתהיה הרוחה תעמדו בקלקולכם:
@117 **והפשתה והשערה נכתה.** נשברה לשון (מלכים ב כג כט) פרעה נכה, (ישעיה טז ז) נכאים, וכן (פסוק לב) לא נכו. ולא יתכן לפרשו לשון הכאה, שאין נו''ן במקום ה''א לפרש נכתה כמו הכתה, נכו כמו הכו, אלא הנו''ן שרש בתבה והרי הוא מגזרת (איוב לג כא) ושפו עצמותיו: **כי השערה אביב.** כבר בכרה ועומדת בקשיה ונשתברו ונפלו. וכן הפשתה גדלה כבר והקשה לעמוד בגבעוליה: **השערה אביב.** עמדה באביה, לשון (שיר השירים ו יא) באבי הנחל:
@118 **כי אפילת הנה.** מאחרות, ועדין היו רכות ויכולות לעמוד בפני קשה. ואף על פי שנאמר (פסוק כה) ואת כל עשב השדה הכה הברד יש לפרש פשוטו של מקרא בעשבים העומדים בקלחם הראויים ללקות בברד. ובמדרש רבי תנחומא יש מרבותינו שנחלקו על זאת ודרשו כי אפילות פלאי פלאות נעשו להם, שלא לקו:
@119 **לא נתך.** לא הגיע, ואף אותן שהיו באויר לא הגיעו לארץ, ודומה לו (דניאל ט יא) ותתך עלינו האלה והשבועה, דעזרא, ותגיע עלינו. ומנחם בן סרוק חברו בחלק (יחזקאל כב כב) כהתוך כסף, לשון יציקת מתכת, ורואה אני את דבריו, כתרגומו ויצק (שמות לח ה) ואתיך, (שם כז) לצקת לאתכא, אף זה לא נתך לארץ לא לארץ: הוצק

@2 **באל שדי.** ר"ל באל שדי במציאותו להשפיע מה שיצטרך לנמצאות באופן היותר שלם וכאלו יאמר שהוא נראה לאבות בזה השם שאם לא יתכן שיהיה מה שייעד להם מצד הסדור המסודר באמצעו' הגרמי' השמימיי' הנה הוא יביא להם זה הטוב מפאת הסדור המסודר מההשגח' האלהית אשר דבקה באבו' הקדושי' מפני השגחה הכוללת הנה תהיה מפני ההשגחה האלהית אשר תדבק לדבקים בו והנה ביארנו זה בשלמות בששי מספר מלחמו' יי':
@2 **ושמי יי' לא נודעתי להם.** ר"ל לישראל והרצון בזה כי בעת ששמי שהוא יי' לא נודע לישר' כמו שהו' נודע עתה על ידך במה שלמדת ידך אותו לזקני ישר' הנה עם כל זה הייתי משתדל להקים אתם בריתי שהיה עם האבות לתת להם רץ כנען ארץ מגוריהם אשר גרו בה והנה קראה ארץ מגוריהם מפני האבו' שגרו בה כמו שאמ' על יצחק רק את בני לא תשוב שמה בעבור אברהם שיצא משם ויותר נפלא מזה שכבר שמעתי גם כן נאקת בני ישר' קודם שהיה שמי נודע להם כמו שנזכר בפרשה הקודמת ובהיות הענין כן הו' מבואר שהם יותר ראויי' עתה שתדבק בהם השגחתי לפי ששמי יי' נודע ביניהם. ולזה ראוי שתבטח שאני אקיים מה שהבטחתיך והנה אמר ושמי יי' לא נודעתי להם ולא אמר ושמי יי' לא נודע להם להעיר על ששמו הוא עצמו ועצמו הוא שמו וזה כי בנמצ' המורכב יקרה שיהיה הגדר בלתי הנגדר באופן מה לפי שהנגדר הוא אחד ובגדר ימצא הרבוי מה כמו שיתבאר באלהיות ואולם השם יתעלה הוא אחד פשוט מכל הפנים ולזה יהיה עצמו ושמו דבר אחד מכל הפנים:
@7 **אשר נשאתי את ידי.** ר"ל אשר נשבעתי טעם כי אשא אל שמים ידי:
@8 **וידבר משה כן אל בני ישראל.** הנה לפי דעתי משה אמר זה לישראל בלא אמצעות אהרן כי כן צוהו השם יתע' במה שאמר לו לכן אמור לבני ישראל:
@10 **בא דבר אל פרעה.** בזולת אמצעות אהרן ולכן אמר משה הן בני ישראל לא שמעו אלי ואיך ישמעני פרעה ואני **ערל שפתים.** והנה הרצון בערל שפתים סתום הדבור ר"ל שננעלו שערי הדבור לפניו כמשפט מי שאינו איש דברים ולזה ביאר במה שאחר זה ידבר יי' אל משה ואל אהרן בכל מה שצוה לאמ' לישראל ולפרעה הרצון בזה שהדבור היה מאתו יתע' למשה שיאמ' זה לאהרן והוא היה המליץ בינו ובין מי שישלחהו השם לדבר אליו והנה אחר שהזכיר תולדו' אהרן ומשה שב לבאר זה שנית:
@25 **הוא אהרן ומשה.** מפני שהיה מדבר עתה בתולדות אהרן הקדים אהרן למשה ועוד שהוא היה גדול ממנו והנה אחר זה כשתארם כשהם מדברים אל פרעה הקדים משה לאהרן כי משה היה העקר בזה:
@30 **ראה נתתיך אלהים לפרעה.** ר"ל שעל דבר פרעה שהיה ירא איך ישמע אליו נתנו השם יתע' לאלהים באופן שיהיה מורה לאהרן מה שיאמר והוא יהיה לו לנביא ולמליץ כמו שאמר בפרשה הקודמת הוא יהיה לך לפה ואתה תהיה לו לאלהים:
@33 **ונתתי את ידי.** ר"ל מכתי והוא כלשון בני אדם בעבור שהיד הוא כלי להכות:
@38 **והשלך לפני פרעה.** כדי שיתבאר לו שהמטה הוא נהפך לנחש באופן שלא ישאר לו ספק על זה. והנה לזאת הסבה השליך אהרן את מטהו לפני פרעה ולפני עבדיו וכן הכה במימי היאור להפכם לדם לעיני פרעה ולעיני עבדיו לזאת הסבה בעינה. וכן ראוי שנאמין שיהיה הענין גן בשאר המכות הנוהגות זה המנהג ואם לא נזכר זה בכלם:
@40 **לחכמים ולמכשפים.** אחשוב שהחכמים היו האנשים שהיו חכמים בחכמת מצרים וענין החכמה ההיא היתה להמיא חכמת הכשוף ויעשו בה פעולות זרות אין מדרך הטבע שיגיעו ממנו וזה אם בשיאחזו העינים ויביאו לחשוב שהם עושים מה שאינם עושי' אם כשימציאו התחבולו' הטבעיות יתחדשו בהם עניני' זרים ידמו מפעולות הכשפים או בשיעשו אלו הפעולות הזרות על דרך כשוף אם היה שיהיה אפשר שיתחדשו בדרך הכשוף כמו אלו הפעולות על דרך האמת. והנה לא נודע לנו עד היו מהות זה הכשוף וענינו. ולה לא ראינו לדבר בו והמכשפים היו האנשים שהיו מעסקי בפעולות הכשוף:
@40 **חרטומי מצרים.** הם החכמים והמכשפים:
@40 **בלהטיהם.** בסתריהן כטעם והמלך לאט את פניו שהרצון בו כסה והסתיר. וידמה שכבר עשו זה באחיזת עיני' וזה שהם הביאו לחשב שיהפכו מטותיהם לתנינים במה שהסתירו והעלימו מאמתת העניין מהאנשי' הרואים זה:
@41 **ויבלע מטה אהרן מטותם.** ר"ל שבעת היותו לתנין בלע שאר התנינים והיו למזון לו עד שכאשר שב למטה לא נמצא שם רק מטה אהרן והוא המטה שהיה ביד משה שצוהו השם יתע' שישאהו בידו שיעשה בו את ואותות וזה לאות' שמטה אהרן היה תנין לפי האמת לא לפי הראות לבד כמו הענין במטות החרטומים ולזה היה ראוי שיתן פרעה אל לבו שיש הבדל נפלא בין מה שיעשוהו החרטומים ובין מה שעשה משה והנה עם כל זה נתחזק לב פרעה ולא שמע אליהם:
@45 **ואמרת אליו יי' אלהי העברים וגו'.** הנה הרצון בזה שיאמר לו זה באמצעות אהרן כמו שקדם:
@47 **והדגה אשר ביאור תמות ובאש היאור ונלאו מצרים.** ר"ל כי בעת שיכה במטה אשר בידו על המים יהפכו לדם ותמות תכף הדגה אשר ביאור ובאש את היאור:
@48 **על מימי מצרים.** הם כלל כל המימות ואחר זה פרט אותם והנה אמר לו שיטה ידו על מימי מצרים לפי שבעת הכותו את היעור יהפכו כלם לדם כאלו נטה ידו עליהם:
@48 **על נהרותם על יאוריהם ועל אגמיהם.** הנה הנהרות הם מימות הנגרים שיש להם בהמ מקור או מקורות יהיו נובעי' ממנו והיאורים הם ג"כ מימות נגרים אלא שאין להם בהם מקור יהיו נובעים ממנו אבל הפכו המים שם ממקום אחר. והאגמים ומקוה המים הם מימות עומדים במקום אחד בלי נגרים וכאשר יהיה שם מהם כמות רב יקראו אגמים וכאשר יהיו מועטים יקראו מקוה המים:
@48 **ובעצים ובאבנים.** רוצה לומר שכבר יהפכו לדם גם כן המים אשר בכלי העצים והאבנים בעת הכותו את היאור:
@51 **ויעשו כן חרטומי מצרים בלטיהם הוא כמו בלהטיהם.** והנה הביאו להם מים מהמקומות אשר חפרו אחר זה כמו שכתב החכם אבן עזרא והפכו אותם לדם לפני פרעה כי לא נהפכו לדם על ידי אהרן רק המים המגולים הנראים על הארץ לא המים אשר תחת לארץ ולזה חפרו המצרים סביבות היאור מים לשתות והנה עם כל זה היה הבדל עצום בין מעשה משה למעשיהם כי הם לא הפכו כי אם מים מעטים היו לפניהם ומשה הפך כל מימי מצרים ברגע אחד:
@52 **ולא שת לבו גם לזאת.** כי הוא חושב שהיו מעשה כשפים ולא נתן לבו להתבונן בהבדל נפלא שבין מעשה המכשפים למעשה משה:
@54 **וימלא שבעת ימים.** רוצה לומר שהמכה הזאת עמדה שבעת ימים וביארה התורה זה בזאת המכה לאות שכל שאר המכות עמדה כל אחת מהן שבעה ימים כי זה מנהג התורה שתבאר הדברים בענין אחד כדי שנלמוד ממנו זה בשאר הענינים הדומים לו כמו שהתבאר בשרשים הכוללים. וארצה באמרי שאר המכות אשר אפשר שיאמר בהם זה כמו הכנים והשחין:
@55 **בא אל פרעה ואמרת אליו.** רוצה לומר שיאמר זה לו באמצעות אהרן וכן הענין בכל הדברים שצוה השם יתע' למשה שיאמר לפרעה כי כבר שמהו השם יתע' לו לפה בכל אשר ישולח אל פרעה כמו שקדם:
@57 **ועלו ובאו בביתך.** הקדימו לפי שהוא היה העקר ולזה היה ראוי שילקח תחלה ולזה גם כן הקדי' עבדיו לעמו כי היתה יד עבדיו במעל אשר מעל בישראל:
@59 **נטה ידך במטך על הנהרות.** הרצון בזה שיטה ידו במטהו בעבור הנהרות והאגמים והיאורי' בדרך שיצאו מהם צפרדעים או אפשר שנטה ידו במטהו אל הצד שהיו בו הנהרות והיאורים והאגמים. והביאור הראשון הוא יותר נכון כי כבר יתכן שהיו במצרים מימות בכל הצדדים:
@60 **ותכס את ארץ מצרים.** רוצה לומר שעלה ממנו רבוי נפלא:
@61 **ויעשו כן חרטומי מצרים בלטיהם.** כבר ביארנוהו במה שקדם והנה יתכן שעשו זה במים מועטים שהביאו לפניהם כמו שכתב החכם אבן עזרא רוצה לומר שהביאו לחשוב שיעלו מהם צפרדעים:
@62 **העתירו אל השם ויסר הצפרדעים.** מפני שלא מצאנו לפרעה שיאמר כן במכת הכנים ידענו כי לא עשה זה כי אם לנסות אם היה זה הפועל בא על ידי משה ואהרן או הוא מקרה קרה להם וידעו זה המקרה משה ואהרן באחד מן הדרכים אשר ידע האדם בהם העתידות ולזה אמר שאם היה כדבריהם שיהיה זה הפעל בא על ידם מאת השם יתעלה יתפללו לשם יתע' שיסיר הצפרדעים ממנו ומעמו ואז יתברר לו אם תסור המכה הזאת כי דבריהם אמת וישלח העם לזבוח ליי' ואמ' משה לפרעה התגדל והשתבח והתפאר עלי להוכיח השקרו' אם ימצא בדברי והנה תבחן עוד כשתגזור הזמן שתרצה שתסור זאת המכה ממך ואני אשתדל בתפילתי עם השם יתע' שיאמינו דבריך והנה אמר לו זה כי משה היה יודע שכונת פרעה היה לנסותם והנה אם אמר לו משה שיעתיר אל יי' ויסורו הצפרדעים היה אפש' שישאר ספק על זה לפרעה ויחשוב כי משה היה חושב שכבר הגיע העת שיסורו הצפרדעי' ולזה רצה משה שיגביל פרע' העת שירצה שיסורו בו. והנה חשב פרעה כי משה אמר זה להיותו משער שכבר הגיע עת סורם כי הוא יחשב שירצה פרעה שיסורו תכף ולזה שם העניין בבחירתו והתחכם פרעה כנגד זאת המחשבה ושאל ממנו שיסורו הצפרדעים למחר:
@63 **למתי אעתיר לך.** אין הרצון בזה מתי אתפלל לך אבל הרצן בו באי זה העת יבחר שיסורו הצפרדעים ויתפלל משה שיסורו בעת ההוא:
@64 **למען תדע כי אין כיי' אלהינו.** הנה אמר זה לפי שפעולות העליונים מוגבלים ומסודרים ולא יוכלו לשנות סדורם ואולם השם יתע' שליט לעשות מה שישאלו ממנו הדבקים בו:
@66 **אשר שם לפרעה.** ר"ל ששם בהם מועד לפרעה שיסורו בו:
@68 **ויצברו.** ויאספו:
@68 **חמרים חמרים.** ר"ל צבורין צבורין:
@69 **וירא פרעה כי היתה הרוחה והכבד את לבו ולא שמע אליהם.** יתכן שבאו לפניו משה ואהרן אחרי שסרו הצפרדעים לבקש ממנו שישלח ישראל כמו שהבטיחם ולא שמע אליהם ואז אמרו לו לפי מה שאחשוב שאם מאן הוא לשלח העם הנה יכה במטה אשר ביום עפר הארץ והיה לכנים וכאשר מאן לשלחם אז צוה משה לאהרן שיכה עפר הארץ והיה לכני' בכל ארץ מצרים כמו שהיה מנהגם בשאר המכות הקודמות כי לא היו מביאים המכות כי אם לתכלית שישלח בני ישראל ממצרים:
@71 **ויך את עפר הארץ ותהי הכנם באדם ובבהמה.** ר"ל שבסף העניין היה הכנם באדם ובבהמה וזה שבתחילה היה כל עפר הארץ כנים בכל ארץ מצרים ואז השתדלו החרטומים להוציא הכנים ולא יכולו ואחר זה עלה הכנם מהארץ באדם ובבהמה ר"ל שבסוף העניין היה הכנם באדם ובבהמה:
@72 **להוציא את הכנים ולא יכולו.** ידמה שלא היה כח במלאכה ההיא להחטיא חוש הראות בכמו אלו ההויות הקטנות ולזה אמרו בבראשית רבה שאין השד שולט בבריאה פחותה מכשעורה:
@73 **אצבע אלהים הוא.** ר"ל שהיא מכת השם יתע' לא פעל נעשה בכשפים ולזה לא יוכלו החרטומים לעשו' כמו זה המעשה כן פירשו בבראשי' רבא ויתכן שהם אמרו שהיא מכת אלהים לפי המערכת ולא נעשה על ידי משה ואהרן כמו שכתב החכם א"ע וכאלו אמר זה להודות שיאן יתרון למשה ולאהרן עליהם:
@74 **ואמרת אליו.** באמצעות אהרן הנני משליח בך מגרה ומשסה בטעם והשלחתי בכם את חית השדה:
@76 **ערוב.** הם חיות מעורבות ממיני' רבים כמו זאבים ושועלים והיו אוכלי' מזונותיהם בבית ובשדה ומשחיתים המקנה:
@76 **והפליתי ביום ההוא את ארץ גשן.** יתכן ששאר המכות היו כוללים לישראל ולמצרים כמו שכתב החכם א"ע:
@76 **למען תדע כי אני יי' בקרב הארץ.** ר"ל שאני משגיח בתחתונים ואע"פ שמעלתי גבוהה מאד וזה שכבר אביא המכה הזאת כך ובעמך ולא אביא אותה בארץ גשן ששם בני ישראל:
@77 **ושמתי פדות בין עמי ובין עמך.** ר"ל שאני אשם ההבדל בין עמי ובין עמך פדות וזה כי לעמי יהיה לו פדות מהמכה הזאת ולא כן לעמך וזהו ההפלגה וההבדל שאמ' השם יתעלה שיפליא ארץ גשן לבלי היות שם ערוב ואפשר שרצה בזה והוא הנכון שגם בארץ גשן לא ימלטו מזאת המכה כי אם הישראלים וזה כי כבר היו שם מצרים כמו שהורה באמרו ושאלה אשה משכנתה או ר"ל בפרות הפרש כמו שכתב החכם אבן עזרא:
@79 **לכו זבחו לאלהיכם בארץ.** ר"ל בארץ מצרים כדי שלא יצאו משם כי היה ירא פרעה שיברחו:
@80 **תועבת מצרים.** כתרגומו כי הם היו עובדים למזל טלה והיו חושבים שיהיה המזל ההוא אלהי מצרים:
@82 **רק הרחק לא תרחיקו ללכת.** יותר מדרך שלשת ימים:
@82 **העתירו בעדי.** שיסור הערוב:
@86 **גם בפעם הזאת.** אמ' זה לפי שפעם אחרת הסכים לשלחם ולא קיים דברו וזה היה במכת הצפרדעי' והנה זה גנות גדול בחק המלכות ר"ל שלא יקיים דבריו וכל שכן בענין הזה וזה כי הוא היה עושה חמס בהכריחו ישראל לעבודת פרך ולזה היה ראוי שישלחם לזבוח להשם ואם לא קדמ' להם מצדו הבטחה על זה עם מה שהיה רואה מהנפלאו' והמכות שהביאם עליו השם יתע' כדי שישלח העם:
@89 **הנה יד יי' הויה.** ר"ל מכת השם יתע' במקנך אשר בשדה הנה זה היה פלא עצום כי זה העפוש אשר נתחדש באויר אז על דרך פלא שהיה ממית המקנה לא נתפשט כי אם באויר שהיה חוץ לעיר:
@92 **וימת כל מקנה מצרים.** ר"ל שמת ממנו הרבה כי הגזירות הכוללות תעשינה בכמו אלו הספורים על זה האופן וכן וישכימו בבקר והנה כלם פגרי' מתים. וכן אמרו כי כלנו מתים בעבור הבכורות שמתו. והנה מתו אשר בשדה ונשארו אשר בעיר ואולי לא מתו כל אשר בשדה כי לא אמר כן משה לפרעה אבל אמ' שיהיה בהם דבר כבד מאד:
@93 **ויכבד לב פרעה ולא שלח את העם.** הנה אף על פי שכבר היה ראוי שיתברר לו שזה פועל אלהי שלא מת אחד ממקנה ישראל והיה בלתי אפשר שיהיה כמו זה ההבדל בין מקנה ישראל ובין מקנה מצרים במקרה הנה עם כל זה הכביד לבו ולא שלח העם כמו שיעד השם יתע' שכבר יחזק לבו כדי שירבו אותותיו ונפלאותיו במרים ויתקרבו ישראל מפני זה לעבודת השם יתע'. וידמה שכבר אמר לו אז שישלח את העם בהתאמת לו דבריהם והוא חזק לבו ואז אמרו לו כי אם מאן הוא לשלח יביאו לו מכת השחין כי לא באו המכות כי אם לתכלית שיצאו בני ישראל ממצרים:
@94 **פיח הכבשן.** הוא הרמץ:
@94 **וזרקו משה השמימה.** אפשר שם משה הכל בכלי אחד וזרקו באויר לצד השמיט'. ורז"ל אמרו בבראשית רבה שכבר נעשה לו נס שהחזיקו מלא חפני משה מלא חפניו ממשה ואהרן:
@96 **פורח.** כתרגומו:
@98 **כאשר דבר יי' ביד משה.** ר"ל שכבר אמר השם יתע' למשה כי הוא יחזיק את לבו:
@100 **כי בפעם הזאת אני שולח את כל מגפותי אל לבך.** ר"ל שישלח הרבה ממכותיו אל לבו. והרצון בזה שיירא לבו ויפחד מהם כי היו בזאת המכה קולות חזקים וברד ואש מתלקחת מתוך הברד. והנה תמצא שכבר פחד מאד פרעה מזאת המכה ולזה אמר בבא המכה חטאתי הפעם יי' הצדיק ואני ועמי הרשעים:
@100 **בעבור תדע כי אין כמוני בכל הארץ.** הרצון בזה כי בקצת הדברים הנמצאים בארץ יתכן שיהיה כח לעליוני' שהם עולים מהשם יתעלה אבל בכל הארץ אין כח לאחד מהן זולתי השם יתעלה וזה כי כל אחד מהעלולים ממנו יש לו כח בסדור זה הנמצא השפל כמו שהתבאר בחמישי ממלחמות השם. ואולם השם יתעלה יש לו כח בכללות זה הסדור והוא מסודר ממנו והוא שליט עליו להניע אותו לאשר ירצה:
@101 **כי עתה שלחתי את ידי ואך.** רוצה לומר אם הייתי רוצה הייתי שולח מכתי ואכה אותך ואת עמך בדבר ולא ימצאו ישראל מונע אחר זה מהיציאה מצרי' לזבוח לי:
@102 **ואולם העמדתיך בעבור.** שתראה כחי ויכנע לבבך ובעבור שיכירו מדרגת מציאותי בכל הארץ כדי שיתקרבו כלם לעבודתי:
@103 **מסתולל.** כובש ורומם כטעם דרך לא סלולה:
@105 **העז.** אסוף:
@109 **ויט משה את מטהו על השמים.** רוצה לומר שנטה מטה לצד השמי' ותהלך אש ארצה הם לפידים הוים מהאיד הקטורי ואולי היו קלים באופן שהיו מהלכים ברדתם לארץ והם נקראים פובדר"ש בלעז ואולי היו יורדים תנועה ישרה והם נקראים לאמ"ש בלעז:
@114 **קולות אלהים.** רוצה לומר קולות חזקים כמו רוח אלהים. כהררי אל. שלהבת יה. כקול שדי. והרצון בזה הפסוק הוא כי מני שראה פרעה שכאשר היה מעתיר משה שתסור המכ' היה מעתיר שתסור למחרת היום ההוא כמו שתראה בעניין הערוב הנה שאל פרעה שתסור עת הזאת המכה תכף ולזה אמר העתירו אל יי' שתסור זאת המכה והוא רב מה שהביא ממנה די בו להכניע לבי לשלח אתכם ולזה בטחו שכבר אשלח אתכם ולא תוסיפון לעמוד כי נפלה יראת השם יתעלה על פני ממה שהביא מזאת המכה:
@115 **כצאתי את העיר אפרוש כפי אל יי'.** זה לאות כי לא היה מתפלל משה לשם יתע' תוך העיר כי אולי לא היתה מוכנת אל שידבק לו כח השפע האלהי באופן שתהיה תפלתו נשמעת או היתה הסבה בזה חוזק התפעלותו מרוע מנהג המצרים ולזה היה צריך שיתבודד מהם בהתפללו לשם יתע' ולזה אמר במה שקדם:
@115 **למען תדע כי ליי' הארץ.** רוצה לומר שהוא משגיח בה ושליט לעשות בה כחפצו:
@116 **כי טרם תיראון מפני יי' אלהים.** ר"ל שטרם שאתפלל עליכם להסיר זאת המכה אתם יראים מהשם יתע' אך אחר זה כי תהיה הרוחה לא תיראו ממנו כמו שספר ואמר אחר זה ויסף לחטא ויכבד לבו הוא ועבדיו.
@117 והנה ספר אח' זה ש **הפשתה והשעורה** הוכו בברד כי היו באופן שהזיק להם ואולם ההטה והכוסמת לא הוכו וכמו זה ספר בשאר המכות אי זה מהדברי' לקו בהם ועוד שכבר הוכרח לזה בזה המקום כי הוא אמר במוחלט כי כל עשב השדה הכה הברד ואת כל עץ השדה שבר ולזה ביאר אי זה מהדברים אשר בשדה הוכו ואיזה מהם לא הוכו:
@119 **ויצא משה מעם פרעה ויעתר אל יי'.** והרצון בו שהוא יצא מן העיר:
@119 **ומטר לא נתך ארצה.** ר"ל שלא נתך מטר מהעננים אשר שם מטר שירד לארץ אחר שפירש משה כפיו אל השם יתע' וזה היה פלא עצום ואולם אנקלוס תרגם שהמטר שהיה יורד לא ירד לארץ וזה יהיה יותר נפלא. ולפי דעתי שאם היה הענין כן הנה היתה מבוארת התורה זה כמו שביארה שאר הפלאים הנפלאי':
@121 **ויחזק לב פרעה.** רוצה לומר שהשם סבב שיהיה לבו חזק כאשר דבר ביד משה:

@1 **וארא אל אברהם על בדברם אל פרעעה.**
@1 **באור דברי הפרשה:**
@1 **כאשר** היה ירא משה שלא יתקיים הטוב שהבטיח השם יתע' לישראל מפני מה שראה שהרע פרעה לעם מאז דברו אליו במלאכות יי' כי זה הביאהו לחשב שתמנע מישר' זאת השגחה האלהית מפני פחיתות ישראל וחסרונם אמר לו שם יתע' אני יי' ר"ל שאני לבדי נמצא מעצמותי תמיד בעניין אחד ושאר הנמצאות קנו המציאות אשר להם ממני ולה הוא ראוי שאהיה שליט בשאר הנמצאות להגיע אותם באשר ארצה והנה נראיתי לאברהם ליצחק וליעקב באל שדי ויעדתי להם לתת ארץ כנען לבניהם בכחי זה השליט על הנמצאו' והנה שמי יי' לא היה נודע לישראל וגם הייתי משתדל עם זה להקים בריתי אתם ר"ל שכבר נמשך מההשגחה לישראל מפני מה שיעדתי לאבותיהם לתת לזרעם ואע"פ ששמי יי' לא היה נודע לישר' עדיין. ולזה לא היו ראויי' מצד עצמ' שתדבק השגחתי בהם ועם כל זה התעוררתי להקים בריתי אתם לתת להם ארץ כנען אשר גרו בה האבות וגם אני שמעתי את נאקת בני ישראל עם חסרונם כשזעקו אלי מכובד העבודה ואזכור בריתי שהיתה עם האבות כמו שקדם הספור בזה בפרשה הקודמת. ובהיות העניין כן הוא מבואר שעתה ששמי יי' הוא נודע להם על ידך במה שלמדת לזקני ישראל הם יותר ראוים שתדבק בהם השגחתי ולה אין ראוי שתירא שתמנע מהם זאת ההשגחה האלהית מצד חסרונם כי כבר יעדתי זה להם בעת שהיו יותר חסרים ממה שהם עתה לכן אמור לבני ישראל אני השם שיכולת בידי לעשות מה שארצה והוצאתי אתכם מתחת יד מצרים מעבודתם הקשה וגאלתי אתכם באמצעו' מכות נפלאות שאביא עליהם ובאמצעות אלו הנפלאות אקח אתכם לי לעם ואהיה לכם לאלהים ולמנהיג מרוב השגחתי בכם ותדעו כי אני יי' המוציא אתכם מתחת עבדות מצרים וזה כי רבוי הנפלאות אשר אחדש שם להוציאכם ממצרי' יביא אתכם להאמין בי שאני השליט על הנמצאות ומשגיח בדבקים כי להצילם מהרע שהם בו ובעבור זה הכביד השם יתע' לבב פרעה כמו שיתבאר בפרשת בא אל פרעה והנה אחר זה תהיו מוכנים אל שתדבק בכם השגחתי באופן שאביא אתכם אל ארץ כנען ואתננה לכם מורשה אני יי' שהיכולת בידי לקיים מה שאגזור והנה דבר משה אלו הדברים אל בני ישראל בזולת אמצעות אהרן ולא האמינו בני ישראל בדברי משה מפני קוצר רוח משה להתבונן בסדור דבריו כראוי כדי שייפה להם זה המאמר באופן שיכנסו דבריו באזניהם והיה זה כן מפני רוב התבודדו' משה בהשגות האלהיות כמו שקדם. ומפני העבוד' הקשה שנתחדש' להם אחר שדבר משה אל פרעה במלאכו' השם יתע' שהביאה אותם ג"כ אל שלא ישמעו לדבריו ואחר זה דבר השם יתע' אל משה שיאמר לפרעה שישלח את בני ישראל מארצו. והתנצל משה כי לא יוכל כי הוא ערל שפתים וה יתכן שיהיה סבה שלא ישמע אליו פרעה כי בני ישראל ג"כ לא שמעו אליו לזאת הסבה והנה חשב משה כי מה שאמר לו השם יתע' בפרש' הקודמת שיהיה לו אהרן לפה יהיה לבד בשליחו' הראושן שהיה שלוח לישראל ולפרעה ובטח שיהיה השם עם פיו ויורנו את אשר ידבר בשליחיות האחרי' כמו שיעד לו מתחלה וכאשר ראה שלא היה הש"י עם פיו במה ששלחו אז לדבר לישראל בקש מהשם יתע' שיתן לו מליץ ובאהו דבר השם יתע' שבכל השליחיות אשר ישלח לפרעה ולישראל להוציא את ישראל מיד מצרים יהיה אהרן מליץ בינותם ואולם אחר זה לא יצטרך לו מליץ בינו ובין בני ישראל כי הם יאמינו בו. והנה זכר תולדו' משה ואהרן לכבודם ומעלתם ולזה החל מתולדו' ראובן כי הוא הבכור וספר תולדותיו ותולדות שמעון הבא אחריו בקצור והאריך בתולדות לוי לכבוד משה ואהרן ולזה זכר כמה שנים היו לוי וקהת ועמרם כי הם היו אבותיהם ולזאת הסבה זכר גם כן אשת עמרם ומשפחתה וזכר שם אשת אהרן ומשפחתה ולא הוצרך להזכיר שם אשת משה כי כבר נשכרה במה שקדם והנה זכר משפחת אשת אלעזר לכבוד פינחס אשר קנה לאלהיו והיה מפני זה ברית השם יתע' אתו כמו שנזכר במה שיבא אחר זה ואחר זה שב לענין הראשון ושב לספר הסבה אשר בעבורה היה אהרן לפה למשה בכל דברי נבואתו אשר היו להוציא בני ישראל ממצרים וזה כי משה אמר לשם ית' כאשר צוהו שידבר אל פרעה מה שצוהו שוהא ערל שפתי' ולא ישמע אליו פרעה והנה קצר בכאן בזה המאמר מה שאמר משה הן בני ישראל לא שמעו אלי כי תכלית הכונה היתה בזה המאמר שלא ישמע אליו פרעה והנה במענה השם יתע' לו קצר בכאן והאריך וזה שהוא קצר בכאן מה שנזכר במענה הקודם שאהרן יהיה לו לפה במה שישולח לדבר לבני ישראל להוציאם ממצרים ולא זכר שיהיה לפה כי אם לפרעה לפי מה שיאמרו לפרעה הוא העקר להוציא בני ישראל ממצרים לא מה שיאמרו לישראל ולזה השמיט בזה המקום שיהיה ארן לפה למשה במה שיוצווה לדבר לבני ישראל להוציאם ממצרים והאריך לזכור מה שאמר אז הש"י למשה כששם לו אהרן לפה כי כבר הפסיק המאמ' ההוא כדי שיזכור תולדו' אהרן לפה כי כבר הפסיק המאמ' ההוא כדי שיזכור תולדו' אהרן ומשה קודם שיזכיר הנפלאות שנעשו על ידיהם לפרעה ולעמו אשר היו כלי' להוציא בני ישראל ממצרים ולהקנותם אמונה אמתית ושאר הפעולות אשר ספרה התורה מהם כי כן מנהג התורה בספוריה והוא גם כן ראוי שיודע מי הוא האיש אשר יסופרו מעשיו ועניניו קודם שיסופר זה ממנו ואם אמר אומר מדוע לא ספר תולדותיהם קודם זה מעת ששולחו משה ואהרן אל פרעה אמרנו לו כי בשליחות הראשון לא היה משתתף אהרן למשה כי אם במקרה וזה שהוא הושם לו לפה בשליחות ההוא לבד ולזה לא זכר תולדותיהן עד העת שהשתתף אהרן למשה בכל השליחויות אשר שולח להוציא ישראל ממצרים ולה אמר בזכרו תולדותיהם. הם המדברים אל פרעה. ר"ל שהם היו מדברים תמיד אליו להוציא ישראל ממצרי' כי על הדבור שלא יהיה כי אם פעם אחת לא יאמר הם המדברים אבל יאמר אשר הם דברו וזה מבואר מאד ומפני זה המתין לזכור תולדותיהם עד עת שהשתתף אהרן למשה בכל הדברים אשר היו לפרעה להוציא ישראל ממצרים והנה אמר השם יתע' למשה ראה נתתיך אלהים לפרעה רוצה לומ' לרב ולמורה על דבר פרעה ואהרן אחיך יהיה המדבר בשליחותך אתה תדבר לאהרן את כל אשר אצוך ואהרן אחיך ידבר על פרעה באופן שישלח בני ישראל מארצו. ואני אקשה את לב פרעה מפני יתרון השגחתי בישראל בעבור האבות באופן שיהיה זה סבה אל שאצטרך להרבו' אותותי ומופתי בארץ מצרים וזה כי מפני שלא ישמע אליכם פרעה אכה את מצרים במכות רבות בדרך שאוציא כל צבאותי והם השבטים שהן עמי בני ישראל מארץ מצרים בשפטים גדולים ובסוף הענין אודיע למצרים כי אני יי' בנטותי את ידי על מצרי' ברדפם אחר. בני ישראל בדרך שיטבעו בים סוף כמו שנזכר בפרשת בשלח, שם נזכר שכבר ידעו המצרים כי השם יתעלה הוא יי' בהכבד בפרעה ברכבו ובפרשיו וזה יהיה סבה שלא ירדפו עוד אחרי בני ישראל ואז תשלם לישראל היציאה מיד המצרים כי לא ישתדלו עוד המצרים לרדוף אחריהם להביאם תחת ידם והנה עשו משה ואהרן כאשר צוה ה' אותם כמו שנזכר אחר זה בפרט בכל אות ואות והנה משה היה בן שמונים שנה ואהרן בן שלש ושמונים שנה כאשר התחילו לדבר אל פרעה בה האופן במלאכות השם יתעלה. והנה ראוי שנתיר ספק מה שיקרה בזה הספור קודם שנמנה תועלות המגיעות ממנו וזה שיש למספק שיספק ויאמר איך יתכן שיעניש השם יתע' פרעה כשלא ישמע אליו והנה הוא הקשה לבו על זה ואנחנו אומרים בהיתר זה הספק שהוא מבואר שפרעה ועמו היו רעים מאד וזה מבואר מדוע מנהגיהם עם ישראל ומדוע מנהגיהן בעריות לפי מה שפרסמה התורה מהם במה שצותה בפרשת העריות שלא נעשה כמעשה ארץ מצרי' ובהיות הענין כן הנה לא היה עול אם היה מגיע השם יתע' להם רעות אף על פי שישמעו אל דבריו לשלח בני ישראל ממצרים וכבר ביארנו ברביעי ממי שהרע יביא השם יתע' לרעים מאד לאחת משתי סבות האחת היא להיו' הרע ההוא להם מסודר מצד הגרמים השמימיים כי הם אינם באופן שישגיח בהם השם יתעלה להצילם מהרע ההוא והשנית היא על צד ההשגחה על הטובים והנה היה זה הרע אשר הגיע השם יתעלה לפרעה ולעמו בהכותו אותם באלו המכו' להשגחה על ישראל שיקנו בזה אמונה שלמה כדי שיוכנו אל שיהיו ראויים לירושת הארץ כאשר יעד השם יתע' אל האבות ולזאת הסבה אמר השם יתע' לאברהם וגם את הגוי אשר יעבודו דן אנכי ואחרי כן יצאו ברכוש גדול כמו שביארנו שם וכן תמצא שהקשה השם יתע' רוח סיחון ואמץ את לבבו לבלתי נתון את ישראל עבור בגבולו להשגחתו על ישראל כדי שיפול בידם ויירשו ארצו. ובכאן נשלם היתרה הספק, ואולם התועלות המגיעות מזה הספור הם ששה:
@1 **התועלת** הראשון הוא בדעות. והוא להודיע שההשגחה האלהית תמשך מהאנשים הטובים בזרעם וזה שישראל לא היו באופן שיתכן שיהיו מושגחין כי לא היה שם יי' נודע להם ועם כל זה השגיח בהם השם יתע' והתעורר להשתדל לתת להם את ארץ כנען כאשר נשבע לאבות ושמע נאקתם כשזעקו אליו מפני בריתו עם האבות כי לולא זה לא יתקיים הברית כי ימותו ישראל מחזק הצרות:
@1 **התועלת** השני הוא בדעות. והוא שההשגחה תהיה לאדם מצד מה שישיג ממציאות השם יתע' ולזה אמר כשרצה לבאר שזאת ההשגחה שהשגיח לישראל לא היתה מצדם אבל היתה מפני האבות כי שם יי' לא נודע לישראל כשהשגיח בהם בזאת ההשגחה וזאת ראיה שלא היתה בהם מצדם. ולזה אין ראוי שירא משה שתסור מהם זאת ההשגחה מפני רוע מעשיהם עם שהם היו אז יותר ראויים אל שתדבק בהם ההשגחה האלהית מפני שהיה נודע להם שם יי' באמצעות משה רבינו ע"ה כמו שביארנו ומזה יתבאר שכל מה שהיה לאדם השגה בשם יתעלה יותר חזקה תהיה ההשגחה האלהית הנמשכת ממנה יותר חזקה וזה כבר ביארנוהו מדרך העיון ברביעי ממ"י:
@1 **התועלת** השלישי הוא בדעות. והוא להודיע שההשגחה האלהית משגחת במושגחים בה להקנותם הטובות הנפשיות ולהצילם מהרעות הנפשיות כמו שהשגיח בהם להקנותם הטובות הגופית ולהצילם מהרעות הגופיו' ולזה תמצא שהשגיח השם יתע' לישראל בעבור האבות להקנותם האמונה האמתית ולהצילם מהאמונות הנפסדות במה שהראה מרבוי אותותיו ומופתיו בארץ מצרים כדי שיזכו אל השלמות האמתי וידעו שהשם יתע' הוא השם והוא יהיה להם מפני זה לאלהים ולמנהיג להשגיח בכל עניניהם באופן שיתכן בהם שיירשו ארץ כנען כמו שנזכר שייעד השם יתע' לאברהם בפרשת לך לך כמו שביארנו שם ר"ל כי כמו זאת השגחה רצוני לומר ירושת הארץ לא היה אפשר שתתקיים לזרע האבות אם לא היו באופן שיהיו ראויין לכמו זאת ההשגחה ואמנם ההצלה מהרע באופן שלא ימותו תחת יד מצרים היה אפשר שתהיה לישראל מצד האבות והנה היה הענין בזאת ההשגחה נפלא מאד ר"ל שכמעט מן הזמן הוציא השם יתע' עם רב בכללו מהאמונות הנפסדות שגדלו בהם והביא אותם אל האמונה האמתית עד שבצאתם מארץ מצרים היו נכונים לקבל זאת התורה השלמה וזהו מה שאמר השם יתע' ואשא אתכם על כנפי נשרים ואביא אתכם אלי ר"ל שהוא הביאם לעבודתו בקלות ובמהירות נפלא כאלו היו דורכי' אל זה התכלית כשישאו אותם על כנפי נשרים ויתעופפו בהתעופפות הנשרים במהירות נפלא כמנהגם ויוליכום אל התכלית המכוון:
@1 **התועלת** הרביעי הוא במדות. והוא שראוי לאדם כשירצה להשיג דבר מה מהאנשים שיסדר דבריו בתכלית מה שאפשר בהם מלקיחת הנפשות למה שירצהו ומיפוי הדברים ההם וקשוטם כדי שיפותו לשמוע אליו כי בזולת זה אפשר שלא ישיג מבוקשו ואף על פי שהיו הדברים ההם להגיע תועלת להם. הלא תראה כי זה המאמר' שהיה מצווה משם שיאמר לישר' עם רוב מה שיש בענינו מהטוב להם ומהפתוי אל שיאמינו בדברים ההם הנה לא שמעו ישראל אל משה מפני קוצר רוח משה מלהשתדל לסדר דבריו באופן שלם בדרך שיפותו להאמין לדבריו:
@1 **התועלת** החמישי הוא להודיע הסבה אשר הכריחה אל שיהיו באמצעו' אהרן כל דברי משה לפרעה ולישראל במה שדבר להם להוציאם ממצרים והנה היתה הסבה בזה כי משה היה ערל שפתים לרב התבודדות במושכלות השכליות האלהיות כמו שביארנו בפרשת אלה שמות:
@1 **התועלת** הששי הוא להודיע תולדות אהרן ומשה כי משה יסד בנבואתו עמוד החזק אשר היו בו ישראל לעם לשם יתע' והוא היה להם לאלהים ולמשגיח והיא זאת התורה השלמה האלהית ואהרן היה ראש למשפחות הכהונה אשר שם אותם השם יתע' מיוחדת לעבודתו בדרך שיורו משפטיו ליעקב ותורתו לישראל כמו שיתבאר במה שיבא. והנה זכר עם זה תולדות פינחס לשלמותו לפי שהוא קנא לאלהיו ושם נפשו בכפו להשבית הפעולות המגונות ולזה היה ברית השם יתע' אתו כמו שנזכר בפרשת פינחס:
@37 **ויאמר יי אל משה וגומר עד סוף הפרשה:**
@37 **ביאור דברי הפרשה:**
@37 והנה דברי זה הספור הם מבוארים מאד. ואולם התועלות המגיעות מזה הספור הם שנים:
@37 **התועלת** הראשון הוא להודיע ולפרסם עוצם יכולת השם יתעלה לשנות טבע המציאות על צד ההשגחה עד שכבר היה מביא בפליאה אלו המכות ומסיר אותם בעת שהיה רוצה ותגיע מעוצם היכולת אשר לו להניע לב האנשים ולהטותו לאשר ירצה שכבר חזק לב פרעה לבלתי שלח את העם עם רוב הסבות שהמציא שהיה ראוי שיסדר בהם קושי לבבו ולזה ג"כ הודיענו בזה הספור שמה שיתחדש מהשם יתעלה על דרך המופת הוא אמתי במציאות ההוא כאלו היה מתחדש מהטבע. ולזה בלע מטה אהרן שאר המטות בהיותו תנין כי הוא היה תנין לפי האמת לא לפי הראות לבד כמו הענין בפעולות החרטומים ומפני זה ג"כ מתה הדגה אשר ביאור ובאש היאור כשנהפכו מימיו לדם כי מימיו היו דם לפי האמת במדרגת הדם אשר יתהוה מהטבע:
@37 **התועלת** השני הוא להודיע בהדרגה אשר נהג בה הש' יתעלה עם פרעה כאשר רצה שישלח ישראל אשר העירונו על ענינה בתועלות הפרשה הקודמת וזה כי תחלה צוה שיעשו לפניו מופת בלתי מצער אותו כלל והוא ההפך המטה לתנין ואחר כן צוה שיעשו לפניו מופת מזיק לו מעט והוא ההפך המימות לדם. כי לא היו מוצאים מים לשתות כי אם בקושי ואחר כן צוה שיעשו לפניו מופת יותר מזיק מזה והוא מופת הצפרדעים אלא שהזיקם היה מעט יותר והם הנקראות ראנו"קיי בלעז והנה הם היו עולות בביתם ובחדר משכבם ועל מטתם ויתר המקומות שזכר והיו מפני זה מצערות האנשים צער מה אלא שלא היה כמו הצער שהגיע להם מהכני' כי הם היו עולים בבשרם תוך לבושיהם והיו עוקצים אותם כמנהג הכנים. ולה הביא עליהם אחר זה מכת הכנים והנה זה הסדור הוא ראוי מהאדון הטוב לאנשים המורדים בו וכן יעשו המלכים במורדים בהם אשר אינם שומעי' לדבריהם וזה כי בהלחמם עליהם ימנעו מהם תחלה מזונותיה' ואח' כן יצערו גופם וייסרום בשוטים או בעקרבי' והנה תמצא שכבר הגיעו בתחלה אלו המוסרים מהש"י לפרע' ביות' קל שאפשר וזה כי הוא לא מנע ממזונותיהם כ"א המים והם ג"כ היו נמצאו' להם אלא שכבר היו נמצאי' להם בקושי ואחר כך הגיע צער חלוש לגופם ואחר זה שב להכביד מכותיהם בהדרגה בזה הסדור בעינו וזה שהוא הביא בתחלת הערוב שהיה משחית המקנה ומזונותיהם אשר בבית ובשדה ואחר כך הוסיף שנית להזיקם במזונותיהם וזה שכבר הביא דבר כבד מאד במקניהם שהיה הזיקו יותר חזק מההיזק שהגיע למקנה מן הערוב עם שה ההיזק הגיע כרגע ולא היו יכולים לקחת בו שום עצה ואין כן הענין להיזק שהיגע מפני הערוב ואח' כן הביא בגופן מה שיצערם צער גדול והוא השחין שהיה פורח אבעבועו' כי השחין שהוא היה בזה התואר הוא מצער מאד ואחר זה שב להכביד מכותיה' בהדרג' בזה הסדר בעינו וזה שכבר הביא תחלה הברד להשחית כל אשר בשד' אשר אי אפש' שישחת מפני הברד למנוע מהמצרי' מזונותיה' ואחר כן הכביד עליהם והביא הארבה הנפלא בגבולם להשחית מה שנשאר להם מהברד והעץ הצומח להם מן השד' כדי שיעדרו מזונותיהם במוחלט והם היו עם זה מצערים גופם צער מה כי מלאו מהם בי המצרים ואחר זה הביא עליהם מה שיצער גופם צער נפלא אלא שלא יגיע ממנו המות והוא החשך החזק שהעמיד להם שלשת ימים באופן שלא קמו איש מתחתיו ולא ראו איש את אחיו כי גם הנר לא היה מאיר להם לפי דעתי וסבת זה היה עובי האויר המחשיך עד שהיו יכולי' למשש אותו. ולזה לא היה אפשר להם לקחת מזונם כראוי בכל אלה השלשה ימים ואחר זה הביא המות בכוריהם והנה הנגע האחרון הכביד מכל הקודמים והנה המכות הראשונות נעשו על ידי אהרן כי לא היה הענינם נפלא באופן המכות שנעשו על ידי משה וזה כי המכות שנעשו על ידי אהרן היה רמוז הדבר שנתחדש ממנו מה שנתחדש על דרך פלא כאלו תאמר כי מהמטה היה תנין ומהמים דם וצפרדעים ומהעפר כנים. ואולם הברד לא נתחדש על ידי משה מהדבר רמוז אליו ולא הארבה ולא החשך. והנה השחין שנתחדש על ידי משה מפיח הכבשן לא היה באופן השתנות המים דם כי לא שב פיח הכבשן שחין אבל נתחדש השחין בעת שזרקו משה לצד השמי' ועם כל זה הנה מפני שידמה באופן זה שיהיה התחדש השחין מדבר רמוז נשתתף בענינו אהרן השתתפות מה כי הוא ממוצע בין מה שיתחדש מדבר רמוז ובין מה שיתחדש לא מדבר רמוז ולהראות אופן המדרגות האלו מהמכות שהיו שלשה מדרגות היה נותן בהם רבי יהודה סימנין דצ"ך עד"ש באח"ב וכללם באלו השלשה תיבות לפי שהמדרגה הראשונה היתה דם צפרדע כנים. והמדרגה השנית היתה ערוב דבר שחין. והמדרגה השלישית היתה ברד ארבה חשך מכות בכורות. כמו שהתבאר מדברנו:
